/* Aurora Story Studio v4 — mobile-first, local-first, low-friction writing studio. */
const STORAGE_KEY = 'aurora_story_studio_v4';
const palette = {
  Aurora:['#a855f7','#7c3aed'], Ocean:['#38bdf8','#2563eb'], Emerald:['#34d399','#059669'],
  Crimson:['#fb7185','#e11d48'], Amber:['#fbbf24','#d97706'], Rose:['#fb7185','#be185d'], Mono:['#d4d4d8','#71717a']
};
const themeLabels={dark:'Dark',system:'System',light:'Light'};
const builtInStyles=[
  {id:'balanced',name:'Aurora Balanced',preview:'Concrete prose, selective detail, natural dialogue, flexible pacing.',tags:['natural','clear','adaptive']},
  {id:'quiet',name:'Quiet Literary',preview:'Restrained description, close observation, subtext-heavy dialogue.',tags:['restrained','subtext','intimate']},
  {id:'epic',name:'Epic Weight',preview:'Large scale and atmosphere, controlled figurative language.',tags:['epic','grand','controlled']},
  {id:'fast',name:'Fast Modern',preview:'Lean paragraphs, active dialogue and quick scene movement.',tags:['fast','lean','dialogue']},
  {id:'cultivation',name:'Cultivation Chronicle',preview:'Mature progression, calm power, world history and earned reveals.',tags:['cultivation','mature','worldbuilding']}
];

const demoStory=()=>({
  id:'demo',title:"The Immortal's Retirement",genre:'Cultivation / Fantasy',status:'Draft',format:'novel',favorite:true,folder:'Favorites',progress:42,
  concept:'A 3,000-year-old immortal leaves the upper realms behind and settles anonymously in a remote lower realm, expecting an ordinary life.',
  premise:'An exhausted immortal emperor chooses quiet life over glory, but the people around him slowly pull him into a world whose small problems have larger roots.',
  styleId:'cultivation',authorProfileId:'',pov:'Third Person Limited',aiWritesUser:true,narrativeDistance:'Close',
  creatorNote:'Tell Aurora what you want in ordinary language. It will handle the planning machinery.',
  characters:[
    {id:'c1',name:'Ruin',role:'Protagonist',type:'character',desc:'Ancient immortal emperor. Calm, observant, quietly humorous. Wants an ordinary life and avoids unnecessary displays of power.',visual:'Tall mature man; understated dark robes; composed face; silver-black hair; relaxed posture.',details:{voice:'Dry, economical, rarely performs emotion.',goals:'Live anonymously and experience ordinary life.',fears:'Being dragged back into upper-realm politics.',knowledge:'Knows the upper realms intimately; knows little about local village politics.'}},
    {id:'c2',name:'Mira',role:'Village Healer',type:'character',desc:'Practical village healer. Blunt, curious and suspicious of people who seem too capable.',visual:'Young adult woman; practical clothing; dark braided hair; focused eyes.',details:{voice:'Direct and practical.',goals:'Keep the village healthy.',fears:'Hidden dangers reaching villagers.',knowledge:'Local terrain, village politics, basic cultivation.'}},
    {id:'c3',name:'Old Jian',role:'Merchant',type:'character',desc:'Talkative local merchant who sees every problem as either business or gossip.',visual:'Older man; travel-worn coat; expressive hands.',details:{voice:'Talkative, teasing, observant.',goals:'Profit and interesting gossip.',fears:'Missing a profitable opportunity.',knowledge:'Trade routes and provincial rumors.'}}
  ],
  locations:[{id:'l1',name:'Cloudreed Village',type:'location',desc:'Small lower-realm settlement surrounded by reed fields and distant mountains.',details:'Quiet village with old cultivation routes running nearby.'},{id:'l2',name:'Old North Road',type:'location',desc:'Trade road connecting the village to a provincial city.',details:'Poorly maintained but active with merchants.'}],
  factions:[{id:'f1',name:'Reed Valley Sect',type:'faction',desc:'A minor cultivation sect that treats the village as its outer territory.',details:'Proud local authority, unaware of Ruin’s real identity.'}],
  items:[{id:'i1',name:'Plain Iron Bell',type:'item',desc:'A cheap bell Ruin keeps above his door.',details:'Ordinary object used as a recurring symbol of quiet life.'}],
  rules:[{id:'r1',name:'Upper-Realm Secrecy',type:'rule',desc:'Ruin’s identity should not be casually discovered.',details:'Hard story truth.'}],
  concepts:[{id:'co1',name:'Quiet Immortality',type:'concept',desc:'The story contrasts enormous power with ordinary life.',details:'Core thematic concept.'}],
  acts:[
    {id:'a1',title:'Act I — The Quiet Life',pct:20,chapters:[{id:'ch1',title:'The House at the Edge',summary:'Ruin arrives, repairs an old house, and meets the village healer. The first sign appears that the village sits on something unusual.',scenes:[{id:'s1',title:'Arrival',objective:'Establish the protagonist and the quiet-life premise.',text:'Ruin stopped at the end of the north road and looked over Cloudreed Village. The houses were small. The fields were green. Nobody bowed.\n\nHe liked that.\n\nA broken cart sat beside the road. A woman was arguing with the driver while three villagers watched. Ruin considered walking past.\n\nThen the wheel came loose.\n\nHe sighed, picked it up, and carried it toward them.'}]}]},
    {id:'a2',title:'Act II — Small Problems',pct:55,chapters:[{id:'ch2',title:'The Village Bell',summary:'Ruin settles into a routine. A small local problem reveals a thread leading toward the sect.',scenes:[{id:'s2',title:'A Curious Sound',objective:'Create a small, character-driven disturbance with wider implications.',text:''}]}]},
    {id:'a3',title:'Act III — What Sleeps Below',pct:85,chapters:[]}
  ],
  memory:{permanentFacts:[{id:'m1',text:'Ruin’s true identity is secret.',tags:['Ruin','identity'],importance:5},{id:'m2',text:'Ruin wants an ordinary life in Cloudreed Village.',tags:['Ruin','goal'],importance:4}],events:[{id:'e1',chapterId:'ch1',sceneId:'s1',text:'Ruin arrived at Cloudreed Village and helped repair a broken cart.',when:'Chapter 1'}],state:{location:'Cloudreed Village',time:'Day 1',weather:'Clear',injuries:[],possessions:['Plain Iron Bell'],openThreads:['Why does the village sit on an unusual cultivation route?']},summaries:[],lastUpdated:new Date().toISOString()},
  branches:[],versions:[],taste:{likes:['concrete action','restrained sensory detail'],dislikes:['generic LLM phrasing','automatic atmospheric smells'],confidence:{'concrete action':3,'restrained sensory detail':3,'generic LLM phrasing':3,'automatic atmospheric smells':2},learning:true,snapshot:null,history:[]},
  customAuthorProfiles:[],notes:[]
});

const defaults={
  settings:{accent:'Aurora',theme:'dark',fontScale:1,readerFont:'Georgia',readerWidth:'medium',readerLineHeight:1.86,readerMargin:22,readerPadding:20,tips:true,api:{provider:'NanoGPT',endpoint:'https://nano-gpt.com/api/v1/chat/completions',key:'',model:'deepseek-v4-pro'},budget:{periodLabel:'$3 / 14 days',limit:3,spent:0},autoMemory:true},
  activeView:'library',activeStoryId:'demo',library:{query:'',sort:'updated',filter:'all',folder:'all'},folders:['Favorites','To Read','Drafts','Finished'],stories:[demoStory()],prefs:{global:{likes:[],dislikes:[],rules:[],authorProfileId:''},snapshots:[]}
};
let state=loadState();
let ui={routeStack:[],modal:null,reader:null,editor:null,returnOverlay:null,settingsDraft:null,toastTimer:null,editorRange:null,swipe:{candidates:[],index:0}};

function uid(p='id'){return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function now(){return new Date().toISOString()}
function clone(v){return JSON.parse(JSON.stringify(v))}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function words(t){return String(t||'').trim().split(/\s+/).filter(Boolean).length}
function story(){return state.stories.find(s=>s.id===state.activeStoryId)||state.stories[0]}
function collection(type){return {character:'characters',location:'locations',faction:'factions',item:'items',rule:'rules',concept:'concepts'}[type]||type}
function allChapters(s){return (s.acts||[]).flatMap(a=>a.chapters||[])}
function allScenes(s){return allChapters(s).flatMap(c=>c.scenes||[])}
function sceneById(s,id){return allScenes(s).find(x=>x.id===id)||allScenes(s)[0]}
function chapterByScene(s,id){return allChapters(s).find(c=>(c.scenes||[]).some(sc=>sc.id===id))}
function chapterNum(s,id){let n=0;for(const c of allChapters(s)){n++;if(c.id===id)return n}return 1}
function totalWords(s){return words(allScenes(s).map(x=>x.text||'').join('\n'))}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
function loadState(){try{return mergeState(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'))}catch{return clone(defaults)}}
function mergeState(p){if(!p)return clone(defaults);const d=clone(defaults);Object.assign(d,p);d.settings={...defaults.settings,...(p.settings||{}),api:{...defaults.settings.api,...(p.settings||{}).api},budget:{...defaults.settings.budget,...(p.settings||{}).budget}};d.library={...defaults.library,...(p.library||{})};d.prefs={...defaults.prefs,...(p.prefs||{}),global:{...defaults.prefs.global,...(p.prefs||{}).global}};d.folders=Array.isArray(p.folders)?p.folders:d.folders;d.stories=Array.isArray(p.stories)&&p.stories.length?p.stories:d.stories;d.activeStoryId=p.activeStoryId||d.stories[0].id;return d}
function applyTheme(){const r=document.documentElement,p=palette[state.settings.accent]||palette.Aurora;r.style.setProperty('--accent',p[0]);r.style.setProperty('--accent2',p[1]);r.style.setProperty('--font-scale',state.settings.fontScale||1);r.dataset.theme=state.settings.theme||'dark'}
function toast(m){const t=document.getElementById('toast');if(!t)return;t.textContent=m;t.classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function tip(label,text){return state.settings.tips?`<button class="tip-btn" data-action="tip" data-tip="${esc(text)}" aria-label="Help: ${esc(label)}">?</button>`:''}
function pageHead(k,t,d,action='',label=''){return `<section class="page-head"><div><div class="eyebrow">${esc(k)}</div><div class="title-row"><h1>${esc(t)}</h1>${tip(t,d)}</div><p>${esc(d)}</p></div>${action?`<button class="btn primary" data-action="${action}">${esc(label)}</button>`:''}</section>`}
function navCard(icon,title,value,desc,target){return `<button class="card soft nav-card" data-action="nav" data-target="${target}"><div class="kpi">${icon}</div><div class="row"><h3>${esc(title)}</h3>${tip(title,desc)}</div><strong>${esc(value)}</strong><div class="muted">${esc(desc)}</div></button>`}

function render(){applyTheme();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.activeView));let root=document.getElementById('view');if(state.activeView==='library')root.innerHTML=renderLibrary();else if(state.activeView==='story')root.innerHTML=renderStory();else if(state.activeView==='write')root.innerHTML=renderWrite();else if(state.activeView==='codex')root.innerHTML=renderCodex();else if(state.activeView==='more')root.innerHTML=renderMore();else if(state.activeView==='plan')root.innerHTML=renderPlan();else if(state.activeView==='memory')root.innerHTML=renderMemory();else if(state.activeView==='authors')root.innerHTML=renderAuthors();else if(state.activeView==='taste')root.innerHTML=renderTaste();else if(state.activeView==='branches')root.innerHTML=renderBranches();else if(state.activeView==='versions')root.innerHTML=renderVersions();else if(state.activeView==='backups')root.innerHTML=renderBackups();else root.innerHTML=renderLibrary();bind();renderOverlay()}

function renderLibrary(){const q=state.library.query.toLowerCase(),stories=state.stories.filter(s=>{const hit=!q||[s.title,s.genre,s.status,s.folder].join(' ').toLowerCase().includes(q);const f=state.library.filter==='favorites'?s.favorite:true;const folder=state.library.folder==='all'||s.folder===state.library.folder;return hit&&f&&folder}).sort((a,b)=>{if(state.library.sort==='title')return a.title.localeCompare(b.title);if(state.library.sort==='created')return String(a.id).localeCompare(String(b.id));return (b.updatedAt||'').localeCompare(a.updatedAt||'')});
return pageHead('Private archive','My Stories','Your entire library in one place. Search, sort, filter, favorite and organize without opening another app.','newStory','✨ New concept')+
`<div class="library-tools card"><div class="row"><label class="grow field-lite">⌕ <input id="librarySearch" value="${esc(state.library.query)}" placeholder="Search stories, genre, folder…" /></label><button class="icon-btn" data-action="showLibraryFilters">☷</button></div><div class="chip-row"><button class="chip ${state.library.filter==='all'?'active':''}" data-lib-filter="all">All</button><button class="chip ${state.library.filter==='favorites'?'active':''}" data-lib-filter="favorites">♥ Favorites</button>${state.folders.map(f=>`<button class="chip ${state.library.folder===f?'active':''}" data-folder-filter="${esc(f)}">${esc(f)}</button>`).join('')}</div></div>
<div class="section-title row"><strong>${stories.length} ${stories.length===1?'story':'stories'}</strong><label class="sort-wrap">Sort <select id="librarySort"><option value="updated" ${state.library.sort==='updated'?'selected':''}>Recently updated</option><option value="title" ${state.library.sort==='title'?'selected':''}>Title</option><option value="created" ${state.library.sort==='created'?'selected':''}>Created</option></select></label></div>
<div class="grid">${stories.map(renderStoryCard).join('')||`<div class="empty card"><strong>No matching stories.</strong><p>Change the filter or create a new concept.</p></div>`}</div>
<div class="section-title">Folders ${tip('Folders','Folders organize stories. A story can be moved between folders without changing its content.')}</div><div class="chip-row folders-row">${state.folders.map(f=>`<button class="folder-pill" data-action="filterFolder" data-folder="${esc(f)}">▰ ${esc(f)}</button>`).join('')}<button class="folder-pill" data-action="newFolder">＋ New folder</button></div>`}
function renderStoryCard(s){const wc=totalWords(s);return `<article class="card story-card"><button class="story-main" data-action="openStory" data-id="${s.id}"><div class="story-cover"><div class="cover-symbol">✦</div></div><div class="story-info"><div class="row"><span class="pill">${esc(s.genre)}</span><span class="tiny">${esc(s.status)}</span></div><h3>${esc(s.title)}</h3><div class="story-meta">${allChapters(s).length} chapters · ${wc.toLocaleString()} words · ${esc(s.folder||'Unsorted')}</div><div class="progress"><span style="width:${Math.min(100,s.progress||0)}%"></span></div></div></button><div class="story-actions"><button class="icon-btn" data-action="toggleFavorite" data-id="${s.id}" aria-label="Favorite">${s.favorite?'♥':'♡'}</button><button class="icon-btn" data-action="editStory" data-id="${s.id}">✎</button><button class="icon-btn" data-action="moveStory" data-id="${s.id}">▣</button><button class="icon-btn danger" data-action="deleteStory" data-id="${s.id}">⌫</button></div></article>`}

function renderStory(){const s=story(),sc=sceneById(s,s.memory?.state?.sceneId),ch=sc?chapterByScene(s,sc.id):allChapters(s)[0],scene=sc||allScenes(s)[0];return pageHead('Story workspace',s.title,`${s.genre} · ${s.pov}`,'storyMenu','⋯')+
`<div class="hero-story card"><div class="row"><div class="grow"><span class="pill">Current</span><h2>${esc(ch?.title||'No chapter yet')}</h2><p class="muted">${esc(ch?.summary||'Your story foundation is ready.')}</p></div><div class="kpi">${s.progress||0}%</div></div><div class="progress"><span style="width:${s.progress||0}%"></span></div><div class="hero-actions"><button class="btn primary" data-action="openScene" data-scene="${scene?.id||''}">📖 Read</button><button class="btn" data-action="nav" data-target="plan">☷ Plan</button><button class="btn" data-action="director">✨ Guide</button></div></div>
<div class="section-title">Story brain</div><div class="grid two">${navCard('◈','Codex',countCodex(s)+' entries','Characters, locations, factions, items, rules and concepts.','codex')}${navCard('☷','Outline',allChapters(s).length+' chapters','Read and edit acts, chapters and scenes.','plan')}${navCard('🧠','Memory',s.memory?.events?.length+' events','Persistent facts, story state, summaries and open threads.','memory')}${navCard('✦','Style & taste',styleName(s),'Author voice and your personal taste stay active.','authors')}</div>
<div class="section-title">Foundation</div><div class="card stack"><div><div class="tiny">Concept</div><p>${esc(s.concept)}</p></div><div><div class="tiny">Premise</div><p>${esc(s.premise)}</p></div></div>`}
function countCodex(s){return ['characters','locations','factions','items','rules','concepts'].reduce((n,k)=>n+(s[k]?.length||0),0)}
function styleName(s){return s.customAuthorProfiles?.find(a=>a.id===s.authorProfileId)?.name||builtInStyles.find(x=>x.id===s.styleId)?.name||'My Taste'}

function renderPlan(){const s=story();return pageHead('Plot brain','Outline','Your map of the novel. Tap any chapter to read it, then edit without losing content.','improvePlan','✨ Improve plan')+`<div class="tip-banner"><strong>Lazy mode:</strong> You don't have to invent every chapter. Ask Aurora to improve or extend the plan. ${tip('Outline','Acts are large story movements. Chapters contain scenes. Scene objectives are fed to the writer automatically.')}</div><div class="stack">${(s.acts||[]).map((a,ai)=>`<section class="card act-card"><div class="row"><div><span class="pill">Act ${ai+1} · ${a.pct||0}%</span><h2>${esc(a.title)}</h2></div><span class="tiny">${a.chapters.length} chapters</span></div><div class="stack">${a.chapters.map((c,ci)=>`<button class="chapter-card" data-action="openChapter" data-ai="${ai}" data-ci="${ci}"><div class="row"><div><strong>Chapter ${chapterNum(s,c.id)} — ${esc(c.title)}</strong><div class="tiny">${c.scenes.length} scene${c.scenes.length===1?'':'s'}</div></div><span class="chev">›</span></div><p>${esc(c.summary)}</p></button>`).join('')||'<div class="empty">No chapters yet.</div>'}</div></section>`).join('')}</div>`}

function renderWrite(){const s=story(),sc=scCurrent(s),ch=chapterByScene(s,sc?.id);return pageHead('Writer',sc?.title||'New scene',`${s.pov} · ${styleName(s)}`,'writingHelp','How this works')+`<div class="write-status row"><div class="stack-inline"><span class="status-pill ok">✓ Style active</span><span class="status-pill">🧠 ${s.taste.learning?'Learning':'Frozen'}</span><span class="status-pill">${s.aiWritesUser?'AI writes you':'You control you'}</span></div><button class="btn ghost small" data-action="sceneSettings">⚙ Scene</button></div><article class="book-view card"><div class="reader-meta"><span>Chapter ${ch?chapterNum(s,ch.id):1}</span><span>•</span><span>${words(sc?.text||'').toLocaleString()} words</span></div><div class="manuscript" id="manuscript">${sc?.text||sc?.html?renderSceneContent(sc):'<span class="empty-inline">This scene has no prose yet. Tap Guide or Write.</span>'}</div></article><div class="writer-dock"><button class="tool-btn" data-action="openEditScene">✎<small>Edit</small></button><button class="tool-btn" data-action="director">✨<small>Guide</small></button><button class="tool-btn" data-action="cleanProse">◒<small>Clean</small></button><button class="tool-btn primary-tool" data-action="swipe">↻<small>Swipe</small></button></div><div class="writer-note">${tip('Swipe','Swipe generates alternative versions of the current scene. None become canon until you accept one.')}<span>Changes are versioned automatically.</span></div>`}
function scCurrent(s){return sceneById(s,s.memory?.state?.sceneId)||allScenes(s)[0]}
function formatPlain(t){return esc(t).replace(/\n\n/g,'</p><p>').replace(/^/,'<p>').replace(/$/,'</p>')}

function renderCodex(){const s=story(),groups=[['Characters','characters','character','👤'],['Locations','locations','location','⌖'],['Factions','factions','faction','⚑'],['Items','items','item','◇'],['Rules','rules','rule','✓'],['Concepts','concepts','concept','◈']];return pageHead('Story brain','Codex','Your persistent world reference. Aurora can create entries from rough ideas and discover missing entries.','newCodex','＋ Add')+`<div class="hero-actions"><button class="btn" data-action="discoverCodex">✨ Discover from manuscript</button></div><div class="tip-banner"><strong>Don't fill forms unless you want to.</strong> Use “Discover from manuscript” and Aurora can build entries from text. ${tip('Codex','A Codex entry is persistent story knowledge. It is separate from current story state, so the model does not need the entire manuscript every time.')}</div><div class="field search-field"><label>Search the Codex</label><input id="codexSearch" placeholder="Search characters, places, rules…"></div><div class="stack">${groups.map(([label,key,type,icon])=>{const arr=(s[key]||[]);return `<section class="card codex-group"><div class="row"><div class="title-row"><h2>${label}</h2>${tip(label,`Open a ${label.toLowerCase().replace(/s$/,'')} to read the full entry.`)}</div><span class="tiny">${arr.length}</span></div><div class="list">${arr.map(x=>`<button class="list-item codex-item" data-action="openCodex" data-type="${type}" data-id="${x.id}"><div class="avatar">${icon}</div><div class="grow"><strong>${esc(x.name)}</strong><div class="tiny">${esc(x.desc||'')}</div></div><span class="chev">›</span></button>`).join('')||'<div class="empty">Nothing here yet.</div>'}</div></section>`}).join('')}</div>`}

async function discoverCodex(){const s=story(),sample=allScenes(s).map(x=>x.text||'').join('\n').slice(-12000);if(!sample)return toast('Write some manuscript text first.');if(!state.settings.api.key)return toast('Add a NanoGPT key to discover entries automatically.');toast('Discovering story entities…');try{const r=await nanoJSON(`Extract new story entities from this manuscript. Return JSON only with keys characters,locations,factions,items,rules,concepts. Only include entities not duplicates of existing names. Keep each object compact with name,desc,details and characters also role,visual. Existing names: ${JSON.stringify(['characters','locations','factions','items','rules','concepts'].flatMap(k=>(s[k]||[]).map(x=>x.name)))}\nMANUSCRIPT:\n${sample}`,'codex-discovery');for(const k of ['characters','locations','factions','items','rules','concepts'])for(const x of Array.isArray(r[k])?r[k]:[])if(x.name&&!s[k].some(y=>String(y.name).toLowerCase()===String(x.name).toLowerCase()))s[k].push({...x,id:uid(k.slice(0,2)),type:k.slice(0,-1)});charge(.025);touch(s);saveState();render();toast('Codex discovery complete.')}catch(e){console.warn(e);toast('Discovery failed. Try again.')}}

function renderMemory(){const s=story(),m=s.memory||{permanentFacts:[],events:[],state:{},summaries:[]};return pageHead('Story brain','Persistent Memory','Aurora keeps a compact memory instead of sending your entire novel back to the model. The manuscript stays untouched.','refreshMemory','↻ Rebuild memory')+`<div class="tip-banner"><strong>How it works:</strong> permanent facts stay forever, current state changes as the story changes, and events/summaries are retrieved only when relevant. ${tip('Persistent memory','Memory is stored with the story on this device. You can inspect, edit or rebuild it at any time.')}</div><div class="grid two"><section class="card"><div class="row"><h3>Current state</h3>${tip('Current state','This is what is true right now in the active story.')}</div><div class="stack compact">${Object.entries(m.state||{}).filter(([k])=>k!=='sceneId').map(([k,v])=>`<div class="stat-row"><span>${esc(k)}</span><strong>${esc(Array.isArray(v)?v.join(', '):v||'—')}</strong></div>`).join('')}</div></section><section class="card"><div class="row"><h3>Open threads</h3>${tip('Open threads','Unresolved questions and promises that can come back later.')}</div><div class="list">${(m.state?.openThreads||[]).map(x=>`<div class="list-item"><span class="avatar">?</span><div class="grow">${esc(x)}</div></div>`).join('')||'<div class="empty">No open threads.</div>'}</div></section></div><section class="card"><div class="row"><h3>Permanent facts</h3><button class="btn small" data-action="addMemoryFact">＋ Add</button></div><div class="list">${(m.permanentFacts||[]).map(x=>`<div class="list-item"><div class="grow"><strong>${esc(x.text)}</strong><div class="tiny">Importance ${x.importance||3}</div></div><button class="icon-btn" data-action="editMemoryFact" data-id="${x.id}">✎</button><button class="icon-btn danger" data-action="deleteMemoryFact" data-id="${x.id}">⌫</button></div>`).join('')||'<div class="empty">No permanent facts yet.</div>'}</div></section><section class="card"><div class="row"><h3>Recent events</h3><span class="tiny">${m.events?.length||0}</span></div><div class="list">${(m.events||[]).slice().reverse().map(x=>`<div class="list-item"><div class="grow"><strong>${esc(x.text)}</strong><div class="tiny">${esc(x.when||'')}</div></div></div>`).join('')||'<div class="empty">No recorded events yet.</div>'}</div></section>`}

function renderAuthors(){const s=story();return pageHead('Voice library','Authors & Styles','Choose a built-in voice, use your Personal Taste, or create a custom author profile from a sample.','newAuthor','＋ Create author')+`<div class="author-grid">${builtInStyles.map(a=>`<article class="card author-card ${s.styleId===a.id?'selected-card':''}"><div class="row"><div><h3>${esc(a.name)}</h3><div class="chip-row">${a.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div></div>${s.styleId===a.id?'<span class="status-pill ok">Active</span>':''}</div><blockquote>${esc(a.preview)}</blockquote><div class="row"><button class="btn" data-action="previewStyle" data-id="${a.id}">Preview</button><button class="btn primary small" data-action="useStyle" data-id="${a.id}">Use</button></div></article>`).join('')}</div><section class="card"><div class="row"><h3>My custom authors</h3>${tip('Custom author','Give Aurora a representative passage. It extracts a reusable style profile. We store the style description, not a claim of exact identity.')}</div><div class="list">${(s.customAuthorProfiles||[]).map(a=>`<div class="list-item"><div class="grow"><strong>${esc(a.name)}</strong><div class="tiny">${esc(a.summary||'Custom profile')}</div></div><button class="btn small" data-action="useCustomAuthor" data-id="${a.id}">Use</button></div>`).join('')||'<div class="empty">No custom authors yet.</div>'}</div></section>`}

function renderTaste(){const t=story().taste,g=state.prefs.global;return pageHead('Personal writing model','My Taste','Aurora learns from what you accept, reject, edit and swipe. Explicit instructions always beat learned preference.','tasteSnapshot','Save snapshot')+`<div class="grid two"><section class="card"><div class="row"><h3>Learning</h3><button class="switch ${t.learning?'on':''}" data-action="toggleTaste"><span></span></button></div><p class="muted">${t.learning?'Aurora is learning from this story.':'Frozen. Your current taste is used but not changed.'}</p><div class="row"><span class="tiny">Project profile</span><strong>${t.history?.length||0} learning events</strong></div></section><section class="card"><h3>Controls</h3><div class="choice-stack"><button class="choice-card" data-action="resetTaste"><strong>↶ Reset learned taste</strong><span>Return this project to its baseline.</span></button><button class="choice-card" data-action="exportTaste"><strong>⇩ Export taste</strong><span>Save your learned profile as JSON.</span></button><button class="choice-card" data-action="importTaste"><strong>⇧ Import taste</strong><span>Use a taste profile from another story.</span></button></div></section></div><div class="grid two"><section class="card"><h3>You tend to like</h3><div class="chip-row">${(t.likes||[]).map(x=>`<span class="taste-tag like">${esc(x)}</span>`).join('')||'<span class="muted">No learned likes yet.</span>'}</div></section><section class="card"><h3>You tend to dislike</h3><div class="chip-row">${(t.dislikes||[]).map(x=>`<span class="taste-tag dislike">${esc(x)}</span>`).join('')||'<span class="muted">No learned dislikes yet.</span>'}</div></section></div><section class="card"><div class="row"><h3>Learning history</h3><button class="btn small" data-action="tasteHistory">Read history</button></div><p class="muted">The engine treats these as evidence, not absolute truth. Temporary scene instructions and explicit requests override them.</p></section>`}

function renderBranches(){const s=story();return pageHead('Safe experiments','Branches','Test alternate plot choices without changing the main story. Only accepted or promoted branches become canon.','newBranch','＋ New branch')+`<div class="list">${(s.branches||[]).map(b=>`<button class="card branch-card" data-action="openBranch" data-id="${b.id}"><div class="row"><h3>${esc(b.name)}</h3><span class="pill">${esc(b.status)}</span></div><p>${esc(b.idea)}</p><div class="tiny">From ${esc(b.parentTitle||'current scene')}</div></button>`).join('')||'<div class="empty">No branches yet.</div>'}</div>`}
function renderVersions(){const s=story();return pageHead('Safety net','Versions','Every accepted edit and generation can become a restore point.','openBackups','Backups')+`<div class="list">${(s.versions||[]).slice().reverse().map(v=>`<button class="card version-card" data-action="openVersion" data-id="${v.id}"><div class="row"><div><strong>${esc(v.label)}</strong><div class="tiny">${new Date(v.createdAt).toLocaleString()}</div></div><span class="chev">›</span></div></button>`).join('')||'<div class="empty">No saved versions yet.</div>'}</div>`}
function renderBackups(){return pageHead('Data safety','Backups & Restore','Your stories live locally in this browser. Export a backup before moving devices or clearing site data.','exportBackup','⇩ Export backup')+`<div class="grid two"><button class="card action-card" data-action="importBackup"><strong>⇧ Restore backup</strong><span class="muted">Choose an Aurora JSON backup.</span></button><button class="card action-card" data-action="showResetConfirm"><strong>↶ Reset application</strong><span class="muted">Return Aurora to its original state.</span></button></div><div class="tip-banner"><strong>Private by default.</strong> Stories are stored locally. Your API key is local browser data and should not be shared inside a backup.</div>`}
function renderMore(){return pageHead('Everything else','More','The advanced systems are here when you need them, but they stay out of your way.')+`<div class="grid two">${navCard('✦','Authors','Voice library','Choose or create author profiles.','authors')}${navCard('🧠','My Taste','Personal writing model','Teach Aurora your preferences and save snapshots.','taste')}${navCard('◈','Memory','Persistent story state','Inspect facts, events, summaries and open threads.','memory')}${navCard('↗','Branches',story().branches.length+' saved','Try alternate routes safely.','branches')}${navCard('◷','Versions',story().versions.length+' saved','Restore earlier versions of scene text.','versions')}${navCard('◫','Timeline','Story state','See what is true right now.','memory')}${navCard('💾','Backups','Export / restore','Protect your local library.','backups')}${navCard('⚙','Settings','Appearance · NanoGPT · reader','Customize Aurora and its connection.','settings')}</div>`}

function renderOverlay(){const root=document.getElementById('modal-root');root.innerHTML='';if(ui.reader)root.innerHTML=readerOverlay(ui.reader);else if(ui.editor)root.innerHTML=editorOverlay(ui.editor);else if(ui.modal)root.innerHTML=modalOverlay(ui.modal);bind()}
function sheet(inner,cls='sheet-full'){return `<div class="overlay" data-action="closeOverlay"><section class="${cls}" data-stop="1">${inner}</section></div>`}
function sheetHead(k,t,d){return `<header class="sheet-head"><div><div class="eyebrow">${esc(k)}</div><h2>${esc(t)}</h2><p>${esc(d||'')}</p></div><button class="icon-btn close-big" data-action="closeOverlay">×</button></header>`}
function readerToolbar(){return `<div class="reader-settings-inline"><button class="chip" data-action="readerFontMinus">A−</button><span>Reader</span><button class="chip" data-action="readerFontPlus">A+</button><button class="chip" data-action="readerFind">⌕ Find</button><button class="chip" data-action="readerSettings">⚙</button></div>`}
function readerOverlay(o){const s=story();if(o.type==='scene'){const sc=sceneById(s,o.id);if(!sc)return '';return sheet(sheetHead('Scene','Read '+(sc.title||'Untitled'),'Focused book reader. The manuscript is the canonical text.')+readerToolbar()+`<div class="reader-scroll book-page" id="readerScroll"><div class="scene-kicker">${esc(sc.objective||'Scene')}</div><article class="reader-prose" style="font-family:${esc(state.settings.readerFont)};line-height:${state.settings.readerLineHeight};padding:${state.settings.readerPadding}px ${state.settings.readerMargin}px;max-width:${state.settings.readerWidth==='wide'?'980px':state.settings.readerWidth==='narrow'?'680px':'820px'}">${renderSceneContent(sc)||'<p>No prose yet.</p>'}</article></div><div class="sheet-footer four"><button class="btn" data-action="closeOverlay">Close</button><button class="btn" data-action="openEditScene">Edit</button><button class="btn" data-action="readerBranch">Branch</button><button class="btn primary" data-action="openWriterFromReader">Write</button></div>`)}
if(o.type==='chapter'){const c=allChapters(s).find(x=>x.id===o.id);return c?sheet(sheetHead('Chapter',c.title,'Read the whole chapter. Tap Edit to change it without losing the manuscript.')+readerToolbar()+`<div class="reader-scroll book-page">${c.scenes.map((sc,i)=>`<section class="chapter-scene"><div class="scene-kicker">Scene ${i+1}</div><h3>${esc(sc.title)}</h3><p class="scene-objective">${esc(sc.objective||'')}</p><article class="reader-prose" style="font-family:${esc(state.settings.readerFont)};line-height:${state.settings.readerLineHeight};padding:${state.settings.readerPadding}px ${state.settings.readerMargin}px">${renderSceneContent(sc)||'<p>No prose yet.</p>'}</article></section>`).join('')}</div><div class="sheet-footer three"><button class="btn" data-action="closeOverlay">Close</button><button class="btn" data-action="editChapter" data-id="${c.id}">Edit</button><button class="btn primary" data-action="writeChapter" data-id="${c.id}">Write</button></div>`):''}
if(o.type==='codex'){const arr=s[collection(o.typeName||o.type)]||[];const item=arr.find(x=>x.id===o.id);return item?sheet(sheetHead(o.label||'Codex',item.name,'Read the complete entry. You can edit it in a large sheet.')+`<div class="reader-scroll"><div class="codex-reader"><div class="reader-badge">${esc(o.label||'Codex')}</div><p class="reader-lead">${esc(item.desc||'')}</p>${item.details?`<section class="reader-section"><h3>Details</h3><p>${esc(item.details)}</p></section>`:''}${item.visual?`<section class="reader-section"><h3>Visual identity</h3><p>${esc(item.visual)}</p></section>`:''}${item.role?`<section class="reader-section"><h3>Role</h3><p>${esc(item.role)}</p></section>`:''}</div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Close</button><button class="btn primary" data-action="editCodex" data-type="${o.typeName}" data-id="${item.id}">Edit entry</button></div>`):''}
if(o.type==='version'){const v=s.versions.find(x=>x.id===o.id);return v?sheet(sheetHead('Version',v.label,'Read or restore this exact saved text.')+`<div class="reader-scroll book-page"><article class="reader-prose">${formatPlain(v.text)}</article></div><div class="sheet-footer three"><button class="btn" data-action="closeOverlay">Close</button><button class="btn" data-action="restoreVersion" data-id="${v.id}">Restore</button><button class="btn primary" data-action="openWriterFromReader">Write</button></div>`):''}
if(o.type==='tasteHistory'){const h=story().taste.history||[];return sheet(sheetHead('Taste','Learning history','What Aurora learned from your choices. It is evidence, not a prison.')+`<div class="reader-scroll"><div class="list">${h.slice().reverse().map(x=>`<div class="history-row"><span class="pill">${esc(x.kind)}</span><div class="grow"><strong>${esc(x.text)}</strong><div class="tiny">${new Date(x.at).toLocaleString()}</div></div><button class="icon-btn" data-action="undoTaste" data-id="${x.id}">↶</button></div>`).join('')||'<div class="empty">No learning events yet.</div>'}</div></div><div class="sheet-footer"><button class="btn primary" data-action="closeOverlay">Done</button></div>`)}
return ''}

function editorOverlay(o){const s=story();if(o.type==='scene'){const sc=sceneById(s,o.id);return sc?sheet(sheetHead('Edit scene',sc.title,'Large writing editor with formatting, images, search-friendly content, and safe versioning.')+richEditor(sc)+`<div class="sheet-footer three"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn" data-action="saveSceneNoClose" data-id="${sc.id}">Save</button><button class="btn primary" data-action="saveSceneClose" data-id="${sc.id}">✓ Save scene</button></div>`):''}
if(o.type==='codex'){const arr=s[o.collection],item=arr.find(x=>x.id===o.id);return item?sheet(sheetHead('Edit entry',item.name,'Everything important is comfortable to edit on mobile.')+`<div class="editor-scroll"><div class="field"><label>Name ${tip('Name','Canonical name used by the story engine.')}</label><input id="ceName" value="${esc(item.name)}"></div><div class="field"><label>Description</label><textarea id="ceDesc">${esc(item.desc||'')}</textarea></div><div class="field"><label>Details</label><textarea id="ceDetails">${esc(item.details||'')}</textarea></div>${o.typeName==='character'?`<div class="field"><label>Visual identity</label><textarea id="ceVisual">${esc(item.visual||'')}</textarea></div><div class="field"><label>Role</label><input id="ceRole" value="${esc(item.role||'')}"></div>`:''}</div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveCodex" data-type="${o.typeName}" data-id="${item.id}">✓ Save</button></div>`):''}
if(o.type==='chapter'){const c=allChapters(s).find(x=>x.id===o.id);return c?sheet(sheetHead('Edit chapter',c.title,'Change the chapter and scene objectives without losing prose.')+`<div class="editor-scroll"><div class="field"><label>Title</label><input id="chTitle" value="${esc(c.title)}"></div><div class="field"><label>Purpose</label><textarea id="chSummary">${esc(c.summary||'')}</textarea></div>${c.scenes.map(sc=>`<div class="subcard"><div class="row"><strong>${esc(sc.title)}</strong><button class="btn small" data-action="openScene" data-scene="${sc.id}">Read</button></div><div class="field"><label>Objective</label><textarea data-scene-objective="${sc.id}">${esc(sc.objective||'')}</textarea></div></div>`).join('')}</div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveChapter" data-id="${c.id}">✓ Save chapter</button></div>`):''}
if(o.type==='storyEdit'){const s2=storyById(o.id);return s2?sheet(sheetHead('Edit story',s2.title,'Change library information without touching the manuscript.')+`<div class="editor-scroll"><div class="field"><label>Title</label><input id="storyTitle" value="${esc(s2.title)}"></div><div class="field"><label>Genre</label><input id="storyGenre" value="${esc(s2.genre)}"></div><div class="field"><label>Status</label><select id="storyStatus"><option>Draft</option><option>Reading</option><option>Finished</option><option>Paused</option></select></div><div class="field"><label>Folder</label><select id="storyFolder">${state.folders.map(f=>`<option value="${esc(f)}" ${s2.folder===f?'selected':''}>${esc(f)}</option>`).join('')}</select></div><div class="field"><label>Concept</label><textarea id="storyConcept">${esc(s2.concept)}</textarea></div><div class="field"><label>Premise</label><textarea id="storyPremise">${esc(s2.premise)}</textarea></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveStory" data-id="${s2.id}">✓ Save</button></div>`):''}
if(o.type==='newFolder')return sheet(sheetHead('Library','New folder','Use folders to organize your archive.')+`<div class="editor-scroll"><div class="field"><label>Folder name</label><input id="newFolderName" placeholder="Research, To Read…"></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveFolder">Create</button></div>`);
return ''}

function richEditor(sc){return `<div class="editor-scroll"><div class="field"><label>Scene title</label><input id="sceneTitle" value="${esc(sc.title||'')}"></div><div class="field"><label>Scene objective ${tip('Scene objective','The target for this scene. You can change it anytime. The AI uses it as direction.')}</label><textarea id="sceneObjective">${esc(sc.objective||'')}</textarea></div><div class="rich-toolbar"><button data-editor-cmd="bold"><b>B</b></button><button data-editor-cmd="italic"><i>I</i></button><button data-editor-cmd="underline"><u>U</u></button><select data-editor-font><option value="">Font</option><option value="Georgia">Georgia</option><option value="Arial">Arial</option><option value="Verdana">Verdana</option><option value="Times New Roman">Times</option><option value="Courier New">Courier</option></select><select data-editor-size><option value="">Size</option><option value="2">Small</option><option value="3">Normal</option><option value="4">Large</option><option value="5">XL</option></select><input type="color" value="#ffffff" data-editor-color title="Text color"><input type="color" value="#ffff66" data-editor-highlight title="Highlight"><button data-action="insertImage">🖼</button><button data-action="editorFind">⌕</button></div><div id="richEditor" class="rich-editor" contenteditable="true" spellcheck="true">${safeRichHTML(sc.html,sc.text)}</div><input id="imageInput" type="file" accept="image/*" hidden></div>`}
function safeRichHTML(html,text){if(html)return html;return formatPlain(text||'').replace(/<p><\/p>/g,'')}

function modalOverlay(name){if(name==='newStory')return sheet(sheetHead('Create','New concept','Start with a messy idea. Aurora builds the foundation for you.')+`<div class="editor-scroll"><div class="tip-banner"><strong>Zero homework.</strong> One sentence is enough. ${tip('Quick build','Aurora creates the concept, premise, cast, world, Codex and outline. You can edit everything later.')}</div><div class="field"><label>Your idea</label><textarea id="newIdea" class="big-idea" placeholder="I want a mature cultivation novel about an invincible immortal who retires...\n\nWrite like you talk. Half-ideas are fine."></textarea></div><div class="field"><label>Format</label><div class="choice-grid"><button class="choice-card selected" data-choice-group="format" data-value="novel"><strong>📖 Novel</strong><span>Chapters, scenes and prose.</span></button><button class="choice-card" data-choice-group="format" data-value="comic"><strong>🎨 Comic</strong><span>Story foundation plus visual planning.</span></button></div></div><div class="field"><label>Starting style</label><div class="choice-grid three">${builtInStyles.slice(0,3).map((a,i)=>`<button class="choice-card ${i===0?'selected':''}" data-choice-group="newStyle" data-value="${a.id}"><strong>${esc(a.name)}</strong><span>${esc(a.preview)}</span></button>`).join('')}</div></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="buildStory">✨ Build everything</button></div>`);
if(name==='settings')return settingsModal();
if(name==='director')return sheet(sheetHead('AI Director','What should happen next?','No prompt engineering. Choose a direction or tell Aurora your idea.')+`<div class="editor-scroll choice-stack"><button class="choice-card director-choice" data-action="directorPick" data-mode="logical"><strong>🧭 Logical</strong><span>Most natural, earned next step.</span></button><button class="choice-card director-choice" data-action="directorPick" data-mode="interesting"><strong>✦ Interesting</strong><span>A stronger creative move that still fits.</span></button><button class="choice-card director-choice" data-action="directorPick" data-mode="bold"><strong>⚡ Bold</strong><span>A risky turn that changes the situation.</span></button><button class="choice-card director-choice" data-action="directorPick" data-mode="own"><strong>✎ My idea</strong><span>Write what you want in ordinary language.</span></button><button class="choice-card director-choice" data-action="directorPick" data-mode="surprise"><strong>🎲 Surprise me</strong><span>Aurora invents a direction using your taste.</span></button></div>`);
if(name==='ownDirection')return sheet(sheetHead('Direction','Tell Aurora what you want','This is an instruction, not a prompt-writing task.')+`<div class="editor-scroll"><textarea id="ownDirection" class="big-idea" placeholder="Example: He realizes the woman knows his secret, but do not reveal why yet."></textarea></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="applyOwnDirection">Use direction</button></div>`);
if(name==='swipe')return swipeModal();
if(name==='clean')return sheet(sheetHead('Prose cleaner','Remove AI-style writing','Keep events and meaning. Reduce decorative filler, generic sensory padding and formulaic phrasing.')+`<div class="editor-scroll"><div class="tip-banner">Aurora will show a clean candidate first. ${tip('Prose cleaner','This is a stylistic cleanup, not a plot rewrite. Use it when a scene sounds generic or overly ornate.')}</div><div class="field"><label>What should be removed?</label><textarea id="cleanNote">Keep the author voice. Remove generic smells, unnecessary weather/sensory setup, purple prose, obvious AI transitions and repetitive emotional explanations.</textarea></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="runClean">✨ Clean prose</button></div>`);
if(name==='newCodex')return sheet(sheetHead('Codex','Add entry','Add only what you need. Aurora can discover the rest later.')+`<div class="editor-scroll"><div class="field"><label>Type</label><select id="newCodeType"><option value="character">Character</option><option value="location">Location</option><option value="faction">Faction</option><option value="item">Item</option><option value="rule">Rule</option><option value="concept">Concept</option></select></div><div class="field"><label>Name</label><input id="newCodeName" placeholder="Name"></div><div class="field"><label>Description</label><textarea id="newCodeDesc" placeholder="A short canonical description…"></textarea></div><div class="field"><label>Details</label><textarea id="newCodeDetails" placeholder="Anything more important…"></textarea></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveNewCodex">＋ Add entry</button></div>`);
if(name==='newAuthor')return sheet(sheetHead('Voice library','Create custom author','Paste a representative passage. Aurora analyzes the patterns and saves a reusable style profile.')+`<div class="editor-scroll"><div class="field"><label>Profile name</label><input id="authorName" placeholder="My Quiet Literary"></div><div class="field"><label>Paste a representative passage</label><textarea id="authorSample" class="big-idea" placeholder="Paste a chapter or several strong paragraphs here…"></textarea></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="analyzeAuthor">Analyze & save</button></div>`);
if(name==='newBranch')return sheet(sheetHead('Branch','New alternate timeline','Your main story remains untouched until you explicitly promote a branch.')+`<div class="editor-scroll"><div class="field"><label>Branch name</label><input id="branchName" placeholder="What if he accepts?"></div><div class="field"><label>What are you testing?</label><textarea id="branchIdea" placeholder="He accepts the invitation and enters the capital early."></textarea></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveBranch">Create branch</button></div>`);
if(name==='storyMenu')return sheet(sheetHead('Story tools','Quick menu','The complicated stuff stays here.')+`<div class="editor-scroll choice-stack"><button class="choice-card" data-action="nav" data-target="plan"><strong>☷ Outline</strong><span>Acts, chapters and scenes.</span></button><button class="choice-card" data-action="nav" data-target="memory"><strong>🧠 Memory</strong><span>Persistent story knowledge.</span></button><button class="choice-card" data-action="nav" data-target="backups"><strong>💾 Backups</strong><span>Export or restore.</span></button><button class="choice-card" data-action="settings"><strong>⚙ Settings</strong><span>Appearance, reader and NanoGPT.</span></button></div>`);
if(name==='readerFind')return sheet(sheetHead('Reader','Find in page','Search the currently open manuscript.')+`<div class="editor-scroll"><div class="field"><input id="readerQuery" placeholder="Search this chapter…"></div><div id="readerFindResults" class="muted"></div></div><div class="sheet-footer"><button class="btn primary" data-action="closeOverlay">Done</button></div>`);
if(name==='editorFind')return sheet(sheetHead('Editor','Find','Search inside the manuscript editor without leaving the page.')+`<div class="editor-scroll"><div class="field"><input id="editorQuery" placeholder="Find text…"></div><div id="editorFindResults" class="muted"></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="applyEditorFind">Find</button></div>`);
if(name==='readerSettings')return readerSettingsModal();
if(name==='libraryFilters')return libraryFiltersModal();
if(name==='confirmDelete')return confirmSheet('Delete story?','This removes the story from this browser. Export a backup first if you need it later.','Delete story','deleteConfirmed');
if(name==='confirmReset')return confirmSheet('Reset Aurora?','This removes local stories, taste, settings and API credentials from this browser.','Reset application','resetConfirmed');
if(name==='confirmRestore')return confirmSheet('Restore backup?','The backup will replace the current local state on this device.','Restore','restoreConfirmed');
if(name==='writingHelp')return helpWriting();
if(name==='sceneSettings')return sceneSettingsModal();
if(name==='memoryFact')return memoryFactModal();
if(name==='tasteReset')return confirmSheet('Reset learned taste?','Your manuscript and Codex remain safe. Only learned preferences for this story will be reset.','Reset taste','tasteResetConfirmed');
return ''}

function settingsModal(){const d=ui.settingsDraft||clone(state.settings);return sheet(`<header class="settings-head"><div><div class="eyebrow">Customize Aurora</div><h2>Settings</h2><p>Everything has a tip. Advanced controls are farther down.</p></div><button class="icon-btn close-big" data-action="closeOverlay">×</button></header><div class="settings-scroll"><section class="settings-section"><h3>Appearance ${tip('Appearance','Theme and accent color change the look of Aurora. Changes are previewed instantly and saved when you tap Save settings.')}</h3><div class="subsection"><label>Accent color</label><div class="color-grid">${Object.keys(palette).map(k=>`<button class="color-choice ${d.accent===k?'selected':''}" data-setting-accent="${k}"><span style="--swatch:${palette[k][0]}"></span>${k}</button>`).join('')}</div></div><div class="field"><label>Theme</label><div class="choice-grid three">${Object.keys(themeLabels).map(k=>`<button class="choice-card ${d.theme===k?'selected':''}" data-setting-theme="${k}"><strong>${themeLabels[k]}</strong><span>${k==='dark'?'Best for night reading.':k==='light'?'Bright paper-like interface.':'Follows your device.'}</span></button>`).join('')}</div></div><div class="field"><label>Interface text size</label><div class="stepper"><button data-setting-font="-0.05">−</button><span>${Math.round((d.fontScale||1)*100)}%</span><button data-setting-font="0.05">＋</button></div></div></section><section class="settings-section"><h3>Reader ${tip('Reader','These controls affect the book reader: font, width, line height, margins and padding.')}</h3><div class="field"><label>Font</label><select id="setReaderFont"><option>Georgia</option><option>Arial</option><option>Verdana</option><option>Times New Roman</option><option>Courier New</option></select></div><div class="field"><label>Width</label><select id="setReaderWidth"><option value="narrow">Narrow</option><option value="medium">Comfortable</option><option value="wide">Wide</option></select></div><div class="field"><label>Line spacing</label><input id="setLineHeight" type="range" min="1.4" max="2.3" step="0.05" value="${d.readerLineHeight||1.86}"></div><div class="field"><label>Side margin</label><input id="setReaderMargin" type="range" min="8" max="48" step="2" value="${d.readerMargin||22}"></div><div class="field"><label>Page padding</label><input id="setReaderPadding" type="range" min="8" max="40" step="2" value="${d.readerPadding||20}"></div></section><section class="settings-section"><h3>NanoGPT ${tip('NanoGPT','Aurora uses your NanoGPT API connection for actual AI generation. The key stays in this browser in this MVP.')}</h3><div class="field"><label>Endpoint</label><input id="setEndpoint" value="${esc(d.api.endpoint)}"></div><div class="field"><label>API key</label><input id="setApiKey" type="password" value="${esc(d.api.key)}" placeholder="Paste your NanoGPT key"></div><div class="field"><label>Model</label><input id="setModel" value="${esc(d.api.model)}"></div><div class="row"><button class="btn" data-action="testNano">Test connection</button><span class="tiny">${d.budget.periodLabel}</span></div></section><section class="settings-section"><h3>Smart behavior</h3><div class="settings-toggle"><div><strong>Automatic story memory</strong><div class="muted">Update memory after accepted edits and generations.</div></div><button class="switch ${d.autoMemory?'on':''}" data-setting-auto-memory><span></span></button></div><div class="settings-toggle"><div><strong>Help tips</strong><div class="muted">Keep the ? explanations visible throughout Aurora.</div></div><button class="switch ${d.tips?'on':''}" data-setting-tips><span></span></button></div></section><section class="settings-section"><h3>Budget</h3><div class="budget-card"><div><div class="tiny">Personal limit</div><div class="budget-number">$${Number(d.budget.spent||0).toFixed(2)} / $${Number(d.budget.limit||3).toFixed(2)}</div></div><button class="btn small" data-action="resetBudget">Reset counter</button></div></section><section class="settings-section"><h3>Data</h3><div class="choice-stack"><button class="choice-card" data-action="exportBackup"><strong>⇩ Export everything</strong><span>Stories, Codex, memory, taste and settings.</span></button><button class="choice-card" data-action="importBackup"><strong>⇧ Restore everything</strong><span>Restore from a previous Aurora JSON backup.</span></button><button class="choice-card" data-action="showResetConfirm"><strong>↶ Reset application</strong><span>Erase local data and return to the demo.</span></button></div></section><section class="settings-section"><h3>Advanced ${tip('Advanced','These controls are intentionally hidden from the normal writing workflow. Later we can add context budgets, retrieval weighting, prompt previews and model routing here.')}</h3><div class="advanced-box">Context compiler, memory retrieval, style lock, prose evaluator, model routing, prompt diagnostics and provider-specific settings belong here. The current MVP keeps the switches minimal.</div></section></div><div class="settings-footer"><button class="btn" data-action="cancelSettings">Cancel</button><button class="btn primary" data-action="saveSettings">✓ Save settings</button></div>`)}
function readerSettingsModal(){const d=state.settings;return sheet(sheetHead('Reader','Reading settings','Adjust the reading experience without opening the full settings page.')+`<div class="editor-scroll"><div class="field"><label>Font</label><select id="rsFont"><option ${d.readerFont==='Georgia'?'selected':''}>Georgia</option><option ${d.readerFont==='Arial'?'selected':''}>Arial</option><option ${d.readerFont==='Verdana'?'selected':''}>Verdana</option><option ${d.readerFont==='Times New Roman'?'selected':''}>Times New Roman</option><option ${d.readerFont==='Courier New'?'selected':''}>Courier New</option></select></div><div class="field"><label>Text size</label><div class="stepper"><button data-reader-setting="size" data-delta="-0.05">−</button><span>${Math.round((d.fontScale||1)*100)}%</span><button data-reader-setting="size" data-delta="0.05">＋</button></div></div><div class="field"><label>Page width</label><select id="rsWidth"><option value="narrow" ${d.readerWidth==='narrow'?'selected':''}>Narrow</option><option value="medium" ${d.readerWidth==='medium'?'selected':''}>Comfortable</option><option value="wide" ${d.readerWidth==='wide'?'selected':''}>Wide</option></select></div><div class="field"><label>Line spacing</label><input id="rsLine" type="range" min="1.4" max="2.3" step="0.05" value="${d.readerLineHeight||1.86}"></div><div class="field"><label>Side margin</label><input id="rsMargin" type="range" min="8" max="48" step="2" value="${d.readerMargin||22}"></div><div class="field"><label>Page padding</label><input id="rsPadding" type="range" min="8" max="40" step="2" value="${d.readerPadding||20}"></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveReaderSettings">✓ Apply</button></div>`) }
function libraryFiltersModal(){return sheet(sheetHead('Library','Filter & organize','Narrow your archive without changing any story.')+`<div class="editor-scroll"><div class="field"><label>Folder</label><select id="filterFolder"><option value="all">All folders</option>${state.folders.map(f=>`<option ${state.library.folder===f?'selected':''}>${esc(f)}</option>`).join('')}</select></div><div class="field"><label>Filter</label><select id="filterFav"><option value="all">All stories</option><option value="favorites">Favorites only</option></select></div><div class="field"><label>Sort</label><select id="filterSort"><option value="updated">Recently updated</option><option value="title">Title</option><option value="created">Created</option></select></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="applyLibraryFilters">Apply</button></div>`)}
function sceneSettingsModal(){const s=story();return sheet(sheetHead('Scene settings','Narrative control','These are runtime preferences. Change them anytime without rewriting your character profile.')+`<div class="editor-scroll"><div class="field"><label>POV</label><select id="scenePov"><option>First Person</option><option>Second Person</option><option>Third Person Limited</option><option>Third Person Omniscient</option></select></div><div class="field"><label>AI writes your actions/dialogue</label><button class="switch ${s.aiWritesUser?'on':''}" data-scene-ai-write><span></span></button></div><div class="field"><label>Author style</label><select id="sceneStyle"><option value="taste">My Taste</option>${builtInStyles.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Sensory detail</label><select id="sceneSensory"><option>Selective</option><option>Low</option><option>Normal</option><option>High</option></select></div><div class="field"><label>Figurative language</label><select id="sceneFig"><option>Low</option><option>Normal</option><option>High</option></select></div><div class="field"><label>Length</label><select id="sceneLength"><option>Short</option><option>Normal</option><option>Long</option><option>Epic</option></select></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveSceneSettings">Save</button></div>`)}
function swipeModal(){const sc=scCurrent(story());if(!sc)return '';const cand=ui.swipe.candidates||[];const idx=Math.max(0,Math.min(ui.swipe.index,cand.length-1));const text=cand[idx]||sc.text||'No candidate yet.';return sheet(sheetHead('Swipe','Alternative generation',`Version ${idx+1} of ${Math.max(cand.length,1)}. Nothing changes until you accept one.`)+`<div class="reader-scroll book-page"><article class="reader-prose">${formatPlain(text)}</article></div><div class="swipe-controls"><button class="icon-btn" data-action="swipePrev">‹</button><div class="swipe-dot-row">${cand.map((_,i)=>`<span class="swipe-dot ${i===idx?'active':''}"></span>`).join('')}</div><button class="icon-btn" data-action="swipeNext">›</button></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Close</button><button class="btn primary" data-action="acceptSwipe" data-index="${idx}">✓ Accept this version</button></div>`)}
function confirmSheet(title,desc,yesAction,action){return sheet(sheetHead('Confirm',title,desc)+`<div class="editor-scroll"><div class="warning-box">This cannot be undone unless you have a backup or version.</div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn danger-btn" data-action="${action}">${esc(yesAction)}</button></div>`)}
function helpWriting(){return sheet(sheetHead('Writing','How Aurora writes with you','You do not need to understand prompts, context windows or system instructions.')+`<div class="reader-scroll"><section class="reader-section"><h3>Guide</h3><p>Use normal language. “Make the meeting tense but do not reveal the secret.” is enough.</p></section><section class="reader-section"><h3>Swipe</h3><p>Try different generations at the same story point. Only the version you accept changes canon.</p></section><section class="reader-section"><h3>Clean</h3><p>Reduce generic LLM prose, decorative sensory padding, purple prose and repeated patterns while preserving events.</p></section><section class="reader-section"><h3>Memory</h3><p>Aurora stores story facts, current state and events separately from the raw manuscript so long books can stay manageable.</p></section></div><div class="sheet-footer"><button class="btn primary" data-action="closeOverlay">Done</button></div>`)}
function memoryFactModal(){return sheet(sheetHead('Memory','Add permanent fact','Use this for something that should remain true unless you deliberately change it.')+`<div class="editor-scroll"><div class="field"><label>Fact</label><textarea id="factText" placeholder="Ruin cannot be recognized by ordinary divination."></textarea></div><div class="field"><label>Importance</label><input id="factImportance" type="range" min="1" max="5" value="4"></div></div><div class="sheet-footer two"><button class="btn" data-action="closeOverlay">Cancel</button><button class="btn primary" data-action="saveMemoryFact">Save fact</button></div>`)}

function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigateView(b.dataset.view));document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handleClick));document.querySelectorAll('[data-overlay-close]').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)closeOverlay()}));document.querySelectorAll('[data-choice-group]').forEach(b=>b.onclick=()=>{const g=b.dataset.choiceGroup;document.querySelectorAll(`[data-choice-group="${g}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.querySelectorAll('[data-lib-filter]').forEach(b=>b.onclick=()=>{state.library.filter=b.dataset.libFilter;state.library.folder='all';saveState();render()});document.querySelectorAll('[data-folder-filter]').forEach(b=>b.onclick=()=>{state.library.folder=b.dataset.folderFilter;saveState();render()});const ls=document.getElementById('librarySearch');if(ls)ls.oninput=e=>{state.library.query=e.target.value;saveState();renderLibraryOnly()};const sort=document.getElementById('librarySort');if(sort)sort.onchange=e=>{state.library.sort=e.target.value;saveState();render()};const cs=document.getElementById('codexSearch');if(cs)cs.oninput=()=>filterCodex(cs.value);const rq=document.getElementById('readerQuery');if(rq)rq.oninput=()=>readerFindLive(rq.value);const rd=document.getElementById('editorQuery');if(rd)rd.oninput=()=>editorFindLive(rd.value);const cf=document.getElementById('filterFav');if(cf)cf.value=state.library.filter;const ff=document.getElementById('filterFolder');if(ff)ff.value=state.library.folder;const fs=document.getElementById('filterSort');if(fs)fs.value=state.library.sort;const sts=document.getElementById('storyStatus');if(sts)sts.value=story().status;const sp=document.getElementById('scenePov');if(sp)sp.value=story().pov;const sa=document.querySelector('[data-scene-ai-write]');if(sa)sa.onclick=()=>sa.classList.toggle('on');document.querySelectorAll('[data-reader-setting="size"]').forEach(b=>b.onclick=()=>{state.settings.fontScale=Math.max(.85,Math.min(1.45,(state.settings.fontScale||1)+Number(b.dataset.delta)));saveState();renderOverlay()});bindSettingsHandlers();bindEditorHandlers()}
function readerFindLive(q){const o=ui.reader||ui.returnOverlay?.value,s=story();let text='';if(o?.type==='scene'){text=sceneById(s,o.id)?.text||''}else if(o?.type==='chapter'){const c=allChapters(s).find(x=>x.id===o.id);text=(c?.scenes||[]).map(sc=>sc.text||'').join('\n')}const count=q?text.toLowerCase().split(q.toLowerCase()).length-1:0;const out=document.getElementById('readerFindResults');if(out)out.textContent=q?`${count} match${count===1?'':'es'}`:'Type to search.'}
function editorFindLive(q){const ed=document.getElementById('richEditor'),out=document.getElementById('editorFindResults');if(!out||!ed)return;const n=q?ed.innerText.toLowerCase().split(q.toLowerCase()).length-1:0;out.textContent=q?`${n} match${n===1?'':'es'} found.`:'Type to search.'}
function renderLibraryOnly(){document.getElementById('view').innerHTML=renderLibrary();bind()}
function syncSettingsInputs(){const d=ui.settingsDraft;if(!d)return;d.api.endpoint=document.getElementById('setEndpoint')?.value.trim()||d.api.endpoint;d.api.key=document.getElementById('setApiKey')?.value||d.api.key;d.api.model=document.getElementById('setModel')?.value.trim()||d.api.model;d.readerFont=document.getElementById('setReaderFont')?.value||d.readerFont;d.readerWidth=document.getElementById('setReaderWidth')?.value||d.readerWidth;d.readerLineHeight=Number(document.getElementById('setLineHeight')?.value||d.readerLineHeight);d.readerMargin=Number(document.getElementById('setReaderMargin')?.value||d.readerMargin);d.readerPadding=Number(document.getElementById('setReaderPadding')?.value||d.readerPadding)}
function bindSettingsHandlers(){const syncLive=()=>syncSettingsInputs();document.querySelectorAll('#setEndpoint,#setApiKey,#setModel,#setReaderFont,#setReaderWidth,#setLineHeight,#setReaderMargin,#setReaderPadding').forEach(e=>e.addEventListener('input',syncLive));document.querySelectorAll('[data-setting-accent]').forEach(b=>b.onclick=()=>{syncSettingsInputs();if(!ui.settingsDraft)return;ui.settingsDraft.accent=b.dataset.settingAccent;applyDraft();refreshSettingsPreserveScroll()});document.querySelectorAll('[data-setting-theme]').forEach(b=>b.onclick=()=>{syncSettingsInputs();if(!ui.settingsDraft)return;ui.settingsDraft.theme=b.dataset.settingTheme;applyDraft();refreshSettingsPreserveScroll()});document.querySelectorAll('[data-setting-font]').forEach(b=>b.onclick=()=>{syncSettingsInputs();if(!ui.settingsDraft)return;ui.settingsDraft.fontScale=Math.max(.85,Math.min(1.35,(ui.settingsDraft.fontScale||1)+Number(b.dataset.settingFont)));applyDraft();refreshSettingsPreserveScroll()});const tipT=document.querySelector('[data-setting-tips]');if(tipT)tipT.onclick=()=>{syncSettingsInputs();ui.settingsDraft.tips=!ui.settingsDraft.tips;refreshSettingsPreserveScroll()};const auto=document.querySelector('[data-setting-auto-memory]');if(auto)auto.onclick=()=>{syncSettingsInputs();ui.settingsDraft.autoMemory=!ui.settingsDraft.autoMemory;refreshSettingsPreserveScroll()};const rf=document.getElementById('setReaderFont');if(rf){rf.value=ui.settingsDraft.readerFont||'Georgia';document.getElementById('setReaderWidth').value=ui.settingsDraft.readerWidth||'medium';document.getElementById('setLineHeight').value=ui.settingsDraft.readerLineHeight||1.86;document.getElementById('setReaderMargin').value=ui.settingsDraft.readerMargin||22;document.getElementById('setReaderPadding').value=ui.settingsDraft.readerPadding||20}}
function applyDraft(){const d=ui.settingsDraft||state.settings,r=document.documentElement,p=palette[d.accent]||palette.Aurora;r.style.setProperty('--accent',p[0]);r.style.setProperty('--accent2',p[1]);r.style.setProperty('--font-scale',d.fontScale||1);r.dataset.theme=d.theme||'dark'}
function refreshSettingsPreserveScroll(){const sc=document.querySelector('.settings-scroll');const y=sc?.scrollTop||0;renderOverlay();requestAnimationFrame(()=>{const n=document.querySelector('.settings-scroll');if(n)n.scrollTop=y})}
function bindEditorHandlers(){document.querySelectorAll('[data-editor-cmd]').forEach(b=>b.onclick=()=>{restoreEditorSelection();document.execCommand(b.dataset.editorCmd,false,null);saveEditorSelection()});const ff=document.querySelector('[data-editor-font]');if(ff)ff.onchange=()=>{restoreEditorSelection();if(ff.value)document.execCommand('fontName',false,ff.value);saveEditorSelection()};const fs=document.querySelector('[data-editor-size]');if(fs)fs.onchange=()=>{restoreEditorSelection();if(fs.value)document.execCommand('fontSize',false,fs.value);saveEditorSelection()};const col=document.querySelector('[data-editor-color]');if(col)col.oninput=()=>{restoreEditorSelection();document.execCommand('foreColor',false,col.value);saveEditorSelection()};const hi=document.querySelector('[data-editor-highlight]');if(hi)hi.oninput=()=>{restoreEditorSelection();document.execCommand('hiliteColor',false,hi.value);saveEditorSelection()};const ed=document.getElementById('richEditor');if(ed){ed.addEventListener('mouseup',saveEditorSelection);ed.addEventListener('keyup',saveEditorSelection)}const img=document.getElementById('imageInput');if(img)img.onchange=()=>insertSelectedImage(img.files?.[0])}
function saveEditorSelection(){const s=window.getSelection?.();if(s&&s.rangeCount)ui.editorRange=s.getRangeAt(0)}
function restoreEditorSelection(){const e=document.getElementById('richEditor');if(!e||!ui.editorRange)return;e.focus();const s=window.getSelection();s.removeAllRanges();s.addRange(ui.editorRange)}

async function handleClick(e){const el=e.currentTarget,a=el.dataset.action;if(!a)return;if(el.closest('.overlay')&&!el.classList.contains('overlay'))e.stopPropagation();if(e.target.closest('[data-stop]') && e.target.closest('[data-stop]')!==el){/* allowed */}
try{switch(a){case'tip':showTip(el.dataset.tip);break;case'nav':navigateView(el.dataset.target);break;case'back':goBack();break;case'newStory':openModal('newStory');break;case'openStory':openStory(el.dataset.id);break;case'toggleFavorite':toggleFav(el.dataset.id);break;case'editStory':openEditor({type:'storyEdit',id:el.dataset.id});break;case'moveStory':moveStory(el.dataset.id);break;case'deleteStory':ui.deleteStoryId=el.dataset.id;openModal('confirmDelete');break;case'newFolder':openEditor({type:'newFolder'});break;case'filterFolder':state.library.folder=el.dataset.folder;saveState();render();break;case'showLibraryFilters':openModal('libraryFilters');break;case'newCodex':openModal('newCodex');break;case'discoverCodex':await discoverCodex();break;case'openCodex':{const t=el.dataset.type;openReader({type:'codex',typeName:t,id:el.dataset.id,label:t[0].toUpperCase()+t.slice(1)});break}case'editCodex':openEditor({type:'codex',typeName:el.dataset.type,collection:collection(el.dataset.type),id:el.dataset.id});break;case'openChapter':openReader({type:'chapter',id:story().acts[+el.dataset.ai].chapters[+el.dataset.ci].id});break;case'editChapter':openEditor({type:'chapter',id:el.dataset.id});break;case'writeChapter':{const c=allChapters(story()).find(x=>x.id===el.dataset.id);if(c&&c.scenes[0]){story().memory.state.sceneId=c.scenes[0].id;saveState();navigateView('write')}}break;case'openScene':openReader({type:'scene',id:el.dataset.scene});break;case'openEditScene':openEditor({type:'scene',id:scCurrent(story())?.id});break;case'openWriterFromReader':closeOverlay();navigateView('write');break;case'openVersion':openReader({type:'version',id:el.dataset.id});break;case'restoreVersion':restoreVersion(el.dataset.id);break;case'director':openModal('director');break;case'directorPick':await directorPick(el.dataset.mode);break;case'ownDirection':openModal('ownDirection');break;case'applyOwnDirection':applyOwnDirection();break;case'swipe':await beginSwipe();break;case'swipePrev':swipeMove(-1);break;case'swipeNext':swipeMove(1);break;case'acceptSwipe':acceptSwipe(+el.dataset.index);break;case'cleanProse':openModal('clean');break;case'runClean':await runClean();break;case'writingHelp':openModal('writingHelp');break;case'sceneSettings':openModal('sceneSettings');break;case'saveSceneNoClose':saveScene(el.dataset.id,false);break;case'saveSceneClose':saveScene(el.dataset.id,true);break;case'insertImage':document.getElementById('imageInput')?.click();break;case'editorFind':findEditor();break;case'applyEditorFind':findEditor();break;case'applyLibraryFilters':applyLibraryFilters();break;case'openSynopsis':openReader({type:'chapter',id:allChapters(story())[0]?.id});break;case'improvePlan':await improvePlan();break;case'newAuthor':openModal('newAuthor');break;case'analyzeAuthor':await analyzeAuthor();break;case'useStyle':useStyle(el.dataset.id);break;case'previewStyle':previewStyle(el.dataset.id);break;case'useCustomAuthor':useCustomAuthor(el.dataset.id);break;case'tasteSnapshot':tasteSnapshot();break;case'toggleTaste':story().taste.learning=!story().taste.learning;saveState();render();break;case'resetTaste':openModal('tasteReset');break;case'tasteResetConfirmed':resetTaste();break;case'tasteHistory':openReader({type:'tasteHistory'});break;case'undoTaste':undoTaste(el.dataset.id);break;case'exportTaste':exportTaste();break;case'importTaste':document.getElementById('tasteInput')?.click();break;case'newBranch':openModal('newBranch');break;case'saveBranch':saveBranch();break;case'openBranch':openBranch(el.dataset.id);break;case'openBackups':navigateView('backups');break;case'exportBackup':exportBackup();break;case'importBackup':ensureInput('backupInput','.json');document.getElementById('backupInput').click();break;case'showResetConfirm':openModal('confirmReset');break;case'resetConfirmed':resetApp();break;case'restoreConfirmed':restoreBackup();break;case'openSettings':openModal('settings');break;case'settings':openModal('settings');break;case'cancelSettings':ui.modal=null;ui.settingsDraft=null;render();break;case'saveSettings':saveSettings();break;case'testNano':await testNano();break;case'resetBudget':state.settings.budget.spent=0;saveState();ui.settingsDraft=clone(state.settings);renderOverlay();toast('Budget counter reset.');break;case'saveNewCodex':saveNewCodex();break;case'saveCodex':saveCodex(el.dataset.type,el.dataset.id);break;case'saveChapter':saveChapter(el.dataset.id);break;case'saveStory':saveStory(el.dataset.id);break;case'ssaveFolder':saveFolder();break;case'saveFolder':saveFolder();break;case'addMemoryFact':openModal('memoryFact');break;case'saveMemoryFact':saveMemoryFact();break;case'editMemoryFact':editMemoryFact(el.dataset.id);break;case'deleteMemoryFact':deleteMemoryFact(el.dataset.id);break;case'refreshMemory':rebuildMemory();break;case'openWriterFromReader':navigateView('write');break;case'readerFind':openModal('readerFind');break;case'readerSettings':openModal('readerSettings');break;case'readerFontMinus':readerAdjust(-.05);break;case'readerFontPlus':readerAdjust(.05);break;case'saveReaderSettings':saveReaderSettings();break;case'readerBranch':openModal('newBranch');break;case'showStoryMenu':openModal('storyMenu');break;case'closeOverlay':closeOverlay();break;case'confirmDelete':deleteConfirmed();break;case'deleteConfirmed':deleteStory(ui.deleteStoryId);break;case'addMemoryFact':openModal('memoryFact');break;case'tasteResetConfirmed':resetTaste();break;case'saveSceneSettings':saveSceneSettings();break;default:if(a==='storyMenu')openModal('storyMenu');}
}catch(err){console.error(err);toast(err?.message||'Something went wrong.')}}

function showTip(text){openModal('tip') ;ui.tipText=text;renderOverlay()}
const oldModal=modalOverlay; // keep compiler reference
const originalModal=modalOverlay;modalOverlay=(name)=>{if(name==='tip')return sheet(sheetHead('Help','What does this mean?','')+`<div class="reader-scroll"><p class="help-big">${esc(ui.tipText||'')}</p></div><div class="sheet-footer"><button class="btn primary" data-action="closeOverlay">Got it</button></div>`);return originalModal(name)};

function navigateView(v){if(state.activeView!==v)ui.routeStack.push(state.activeView);state.activeView=v;ui.reader=null;ui.editor=null;ui.modal=null;saveState();render();window.scrollTo({top:0,behavior:'smooth'})}
function goBack(){if(ui.modal||ui.reader||ui.editor){closeOverlay();return}const prev=ui.routeStack.pop();state.activeView=prev||'library';saveState();render()}
function openStory(id){if(!state.stories.some(s=>s.id===id))return;state.activeStoryId=id;ui.routeStack.push(state.activeView);state.activeView='story';saveState();render()}
function storyById(id){return state.stories.find(s=>s.id===id)}
function closeOverlay(){if(ui.returnOverlay){const ret=ui.returnOverlay;ui.returnOverlay=null;ui.modal=null;ui.settingsDraft=null;if(ret.kind==='reader')ui.reader=ret.value;if(ret.kind==='editor')ui.editor=ret.value;renderOverlay();return}ui.modal=null;ui.reader=null;ui.editor=null;ui.settingsDraft=null;render()}
function openModal(n){if(ui.reader){ui.returnOverlay={kind:'reader',value:clone(ui.reader)};ui.reader=null}else if(ui.editor){ui.returnOverlay={kind:'editor',value:clone(ui.editor)};ui.editor=null}ui.modal=n;if(n==='settings')ui.settingsDraft=clone(state.settings);renderOverlay()}
function openReader(o){ui.returnOverlay=null;ui.modal=null;ui.editor=null;ui.reader=o;renderOverlay()}
function openEditor(o){if(ui.reader){ui.returnOverlay={kind:'reader',value:clone(ui.reader)}}else ui.returnOverlay=null;ui.modal=null;ui.reader=null;ui.editor=o;renderOverlay()}

function toggleFav(id){const s=storyById(id);if(!s)return;s.favorite=!s.favorite;s.folder=s.favorite?'Favorites':(s.folder==='Favorites'?'Drafts':s.folder);touch(s);saveState();render();toast(s.favorite?'Added to Favorites':'Removed from Favorites')}
function touch(s){s.updatedAt=now()}
function deleteStory(id){state.stories=state.stories.filter(s=>s.id!==id);if(!state.stories.length)state.stories=[demoStory()];if(state.activeStoryId===id)state.activeStoryId=state.stories[0].id;ui.modal=null;saveState();render();toast('Story deleted.')}
function moveStory(id){ui.moveStoryId=id;openModal('moveStory')}
const originalModal2=modalOverlay;modalOverlay=(name)=>{if(name==='moveStory'){const s=storyById(ui.moveStoryId);return sheet(sheetHead('Library','Move story',`Move “${s?.title||''}” to a folder.`)+`<div class="editor-scroll choice-stack">${state.folders.map(f=>`<button class="choice-card" data-action="chooseMoveFolder" data-folder="${esc(f)}"><strong>${esc(f)}</strong><span>${s?.folder===f?'Current folder':'Move here'}</span></button>`).join('')}</div>`)}return originalModal2(name)};
const originalModal3=modalOverlay;modalOverlay=(name)=>{if(name==='chooseMoveFolder')return '';return originalModal3(name)};
// Add move action through delegated dynamic handler by preprocessing in handleClick wrapper below.
const baseHandleClick=handleClick;handleClick=async function(e){if(e.currentTarget?.dataset?.action==='chooseMoveFolder'){const s=storyById(ui.moveStoryId);if(s){s.folder=e.currentTarget.dataset.folder;touch(s);saveState();closeOverlay();render();toast('Story moved.')}return}return baseHandleClick(e)};

async function buildStory(){const idea=document.getElementById('newIdea')?.value.trim();if(!idea){toast('Give Aurora an idea first.');return}const formatSel=document.querySelector('[data-choice-group="format"].selected')?.dataset.value||'novel';const style=document.querySelector('[data-choice-group="newStyle"].selected')?.dataset.value||'balanced';toast('Building your story foundation…');let result=null;if(state.settings.api.key){try{result=await nanoJSON(`Build a compact story foundation from this idea. Return JSON only with keys: title,genre,concept,premise,characters,locations,factions,items,rules,concepts,acts. Each act has title,pct,chapters; each chapter has title,summary,scenes; each scene has title,objective. Character objects need name,role,desc,visual,details object with voice,goals,fears,knowledge. Do not copy any living author's style. Idea: ${idea}`,'foundation')}catch(e){console.warn(e)}}const s=makeStoryFromFoundation(result,idea,formatSel,style);state.stories.unshift(s);state.activeStoryId=s.id;ui.modal=null;saveState();render();toast('Foundation ready. Your Codex and outline are already built.')}
function makeStoryFromFoundation(r,idea,format,style){r=r||{};const s=clone(demoStory());s.id=uid('story');s.title=r.title||idea.split(/[.!?]/)[0].slice(0,45)||'Untitled Story';s.genre=r.genre||'Fantasy';s.concept=r.concept||idea;s.premise=r.premise||'Aurora will develop the premise from your concept.';s.format=format;s.styleId=style;s.favorite=false;s.folder='Drafts';s.status='Draft';s.progress=25;s.createdAt=now();s.updatedAt=now();for(const k of ['characters','locations','factions','items','rules','concepts'])s[k]=Array.isArray(r[k])?r[k].map(x=>({...x,id:uid(k.slice(0,2))})):[];s.acts=Array.isArray(r.acts)?r.acts.map(a=>({...a,id:uid('act'),chapters:(a.chapters||[]).map(c=>({...c,id:uid('ch'),scenes:(c.scenes||[]).map(sc=>({...sc,id:uid('sc'),text:sc.text||''}))}))})):[];if(!s.acts.length)s.acts=[{id:uid('act'),title:'Act I',pct:25,chapters:[{id:uid('ch'),title:'Chapter 1',summary:'Opening chapter.',scenes:[{id:uid('sc'),title:'Opening',objective:'Establish the protagonist and story promise.',text:''}]}]}];s.memory=blankMemory();s.customAuthorProfiles=[];return s}
function blankMemory(){return{permanentFacts:[],events:[],state:{location:'',time:'',weather:'',injuries:[],possessions:[],openThreads:[],sceneId:''},summaries:[],lastUpdated:now()}}

async function improvePlan(){const s=story();toast('Improving outline…');if(state.settings.api.key){try{const raw=await nanoJSON(`Review this story outline and return JSON only with an improved acts array. Preserve established facts and mature tone. Create coherent act progression, chapters and scene objectives. Current outline: ${JSON.stringify(s.acts)}`,'plan');if(Array.isArray(raw))s.acts=raw;else if(Array.isArray(raw.acts))s.acts=raw.acts;charge(.025)}catch(e){console.warn(e);toast('Outline could not be improved right now.')}}else{toast('Add a NanoGPT key to use AI plan improvement.');return}touch(s);saveState();render();toast('Outline refreshed.')}
async function directorPick(mode){if(mode==='own'){openModal('ownDirection');return}const sc=scCurrent(story());if(!sc)return;let dir=mode==='logical'?'Create the most natural next beat consistent with character motivations and current stakes.':mode==='interesting'?'Choose a more interesting but still credible development.':mode==='bold'?'Introduce a bold development that creates meaningful change.':'Invent a surprising direction consistent with the story and my taste.';const box=document.getElementById('ownDirection');if(mode==='own'&&box)dir=box.value;await generateToScene(sc,dir);}
function applyOwnDirection(){const d=document.getElementById('ownDirection')?.value.trim();if(!d)return toast('Tell Aurora what you want.');const sc=scCurrent(story());if(sc){story().notes.unshift({id:uid('note'),sceneId:sc.id,text:d,createdAt:now()});touch(story());saveState();closeOverlay();toast('Direction saved for this scene.')}}

async function generateToScene(sc,direction){toast('Aurora is writing…');const s=story();let text='';if(state.settings.api.key){try{const prompt=buildPrompt(s,sc,direction);text=await window.nanoGPTGenerate([{role:'system',content:prompt.system},{role:'user',content:prompt.user}],{temperature:.78,max_tokens:1800});charge(Math.max(0,words(text)/1000*.01))}catch(e){console.warn(e)}}if(!text)text=localGenerate(sc,direction,s);saveVersion(sc,'Before generation');sc.text=(sc.text?sc.text+'\n\n':'')+text;sc.html='';updateMemoryFromScene(s,sc,direction,text);touch(s);saveState();ui.modal=null;render();toast('Scene generated and memory updated.')}
function buildPrompt(s,sc,direction){const relevant=s.memory.permanentFacts.slice(0,8).map(x=>x.text).join('; ');const stateTxt=JSON.stringify(s.memory.state);const taste=s.taste.dislikes.slice(0,8).join(', ');const style=styleDescription(s);return{system:`You are Aurora's novel writer. Write finished prose, not explanations. Preserve story facts. Current POV: ${s.pov}. AI writes user actions: ${s.aiWritesUser?'yes':'no'}. Author/style profile: ${style}. Personal taste dislikes: ${taste||'none'}. Avoid automatic decorative sensory details and generic LLM phrasing; sensory details must earn their place. Do not add metaphors merely to decorate. Use concrete, specific prose. Current persistent facts: ${relevant}. Current state: ${stateTxt}.`,user:`Story: ${s.title}\nScene objective: ${sc.objective}\nDirection: ${direction}\nPrevious prose: ${sc.text.slice(-5000)}`}}
function localGenerate(sc,direction,s){const d=direction.toLowerCase();if(d.includes('suspicious'))return `Ruin looked at her again before answering. The question was ordinary. Her timing was not.\n\n"You already knew," he said.\n\nMira held his gaze. She did not explain herself.\n\nThat was enough to make the quiet afternoon feel less quiet.`;if(d.includes('surprising')||d.includes('interesting'))return `The interruption came from the road. Old Jian appeared with a sealed letter and an expression that said he had already regretted opening it.\n\n"This was addressed to you," he said.\n\nRuin took the letter. He had not given anyone in the village his name.`;return `Ruin considered the situation, then chose the smaller response. He had spent three thousand years learning that problems often became larger when answered with too much force.\n\n"Fine," he said. "Show me."`}

async function beginSwipe(){const s=story(),sc=scCurrent(s);if(!sc)return;toast('Generating alternatives…');let cand=[];if(state.settings.api.key){try{const base=buildPrompt(s,sc,'Generate an alternative version of this same scene outcome. Keep canon facts and scene objective intact. Vary the prose approach while following my taste.');const out=await nanoGPTGenerate([{role:'system',content:base.system+' Return three distinct prose alternatives as a JSON array of strings.'},{role:'user',content:base.user}],{temperature:.86,max_tokens:3600});cand=JSON.parse(out.replace(/^```json|```$/g,'').trim());if(!Array.isArray(cand))cand=[];charge(.05)}catch(e){}}if(!cand.length)cand=[localGenerate(sc,'logical',s),localGenerate(sc,'interesting',s),localGenerate(sc,'surprise',s)];ui.swipe={candidates:cand,index:0};openModal('swipe')}
function swipeMove(delta){if(!ui.swipe.candidates.length)return;ui.swipe.index=(ui.swipe.index+delta+ui.swipe.candidates.length)%ui.swipe.candidates.length;renderOverlay()}
function acceptSwipe(i){const s=story(),sc=scCurrent(s),cand=ui.swipe.candidates[i];if(!sc||!cand)return;saveVersion(sc,'Before accepted swipe');sc.text=cand;sc.html='';updateMemoryFromScene(s,sc,'Accepted swipe',cand);learnTaste('like','selected swipe matched taste');touch(s);saveState();closeOverlay();toast('Swipe accepted and made canonical.')}

async function runClean(){const s=story(),sc=scCurrent(s);if(!sc)return;toast('Cleaning prose…');let cleaned='';if(state.settings.api.key){try{const out=await nanoJSON(`Clean this prose while preserving plot, facts, dialogue, actions and meaning. Follow this user's taste: low decorative sensory description, low purple prose, no generic atmospheric smells, no stock AI transitions, concrete wording, natural rhythm. Return only the cleaned prose.\n\n${sc.text}`,'clean');cleaned=out;charge(.03)}catch(e){}}if(!cleaned)cleaned=localClean(sc.text);saveVersion(sc,'Before prose cleanup');sc.text=cleaned;sc.html='';updateMemoryFromScene(s,sc,'Prose cleanup',cleaned);touch(s);saveState();closeOverlay();render();toast('Prose cleaned without changing the story.')}
function localClean(t){let x=String(t||'');const bad=[/the smell of ozone/gi,/the smell of diesel/gi,/the scent of spices/gi,/a chill ran down/gi,/a storm of emotions/gi,/his heart hammered in his chest/gi,/she felt a sense of/gi,/he felt a sense of/gi,/the air was thick with/gi,/hung in the air/gi,/like a silver coin/gi,/for a moment, /gi];bad.forEach(r=>{x=x.replace(r,'')});x=x.replace(/\bnot\s+([^,.]+),?\s+but\s+/gi,'');x=x.replace(/\s{2,}/g,' ');return x}

function saveVersion(sc,label){const s=story();s.versions.push({id:uid('ver'),label,sceneId:sc.id,text:sc.text,createdAt:now()})}
function restoreVersion(id){const v=story().versions.find(x=>x.id===id),sc=sceneById(story(),v?.sceneId);if(!v||!sc)return;saveVersion(sc,'Before restore');sc.text=v.text;sc.html='';updateMemoryFromScene(story(),sc,'Restored version',v.text);touch(story());saveState();closeOverlay();render();toast('Version restored.')}
function updateMemoryFromScene(s,sc,reason,text){if(!s.memory)s.memory=blankMemory();s.memory.events=s.memory.events||[];const ch=chapterByScene(s,sc.id);s.memory.state.sceneId=sc.id;s.memory.events.push({id:uid('evt'),chapterId:ch?.id,sceneId:sc.id,text:reason+': '+summarizeLocal(text),when:ch?`Chapter ${chapterNum(s,ch.id)}`:'Current'});s.memory.lastUpdated=now();if(s.memory.events.length>80)s.memory.events=s.memory.events.slice(-80);const names=[...s.characters,...s.locations,...s.factions,...s.items].map(x=>x.name);const found=names.filter(n=>text.toLowerCase().includes(String(n).toLowerCase()));for(const n of found.slice(0,5)){const fact=`${n} appears in the current scene.`;if(!s.memory.permanentFacts.some(x=>x.text===fact))s.memory.permanentFacts.push({id:uid('mf'),text:fact,tags:[n],importance:2})}}
function summarizeLocal(t){return String(t||'').replace(/\s+/g,' ').trim().slice(0,180)}
function rebuildMemory(){const s=story();s.memory=blankMemory();for(const sc of allScenes(s))if(sc.text)updateMemoryFromScene(s,sc,'Rebuilt',sc.text);saveState();render();toast('Persistent memory rebuilt.')}
function addMemoryFact(text,importance=3){story().memory.permanentFacts.push({id:uid('mf'),text,tags:[],importance});touch(story());saveState();}
function saveMemoryFact(){const t=document.getElementById('factText')?.value.trim();if(!t)return;const imp=+document.getElementById('factImportance').value||3;if(ui.editMemoryId){const x=story().memory.permanentFacts.find(v=>v.id===ui.editMemoryId);if(x){x.text=t;x.importance=imp}ui.editMemoryId=null;touch(story());saveState()}else addMemoryFact(t,imp);closeOverlay();render();toast('Permanent fact saved.')}
function editMemoryFact(id){const x=story().memory.permanentFacts.find(v=>v.id===id);if(!x)return;ui.editMemoryId=id;openModal('memoryFact');setTimeout(()=>{const t=document.getElementById('factText');const im=document.getElementById('factImportance');if(t)t.value=x.text;if(im)im.value=x.importance||3},0)}
function deleteMemoryFact(id){story().memory.permanentFacts=story().memory.permanentFacts.filter(x=>x.id!==id);saveState();render();toast('Memory fact removed.')}

function useStyle(id){story().styleId=id;story().authorProfileId='';touch(story());saveState();render();toast('Style applied to this story.');}
function previewStyle(id){const a=builtInStyles.find(x=>x.id===id);if(!a)return;ui.tipText=`Preview:\n\n${a.preview}`;openModal('tip')}
function useCustomAuthor(id){story().authorProfileId=id;touch(story());saveState();render();toast('Custom author style applied.')}
async function analyzeAuthor(){const name=document.getElementById('authorName')?.value.trim()||'My Custom Author',sample=document.getElementById('authorSample')?.value.trim();if(!sample)return toast('Paste a representative sample first.');toast('Analyzing writing patterns…');let profile=null;if(state.settings.api.key){try{profile=await nanoJSON(`Analyze the supplied writing sample and return JSON only with keys: summary,voice,sentenceRhythm,descriptionDensity,dialogue,metaphorUse,sensoryUse,pacing,showTell,patternsToAvoid,patternsToPrefer. Do not identify the author or promise exact imitation. Describe observable style characteristics. Sample:\n${sample}`,'author')}catch(e){}}if(!profile)profile={summary:'Personal custom profile built from your sample.',voice:'Natural and specific',sentenceRhythm:'Mixed with deliberate variation',descriptionDensity:'Selective',dialogue:'Natural and character-driven',metaphorUse:'As observed in sample',sensoryUse:'Selective',pacing:'Adaptive',showTell:'Balanced',patternsToAvoid:['generic filler','over-explaining'],patternsToPrefer:['specific actions','natural dialogue']};const a={id:uid('author'),name,summary:profile.summary,profile};story().customAuthorProfiles.push(a);touch(story());saveState();closeOverlay();render();toast('Custom author saved to your library.')}
function styleDescription(s){if(s.authorProfileId){const a=s.customAuthorProfiles.find(x=>x.id===s.authorProfileId);if(a)return JSON.stringify(a.profile)}const a=builtInStyles.find(x=>x.id===s.styleId);return a?`${a.name}: ${a.preview}`:"Use the user’s Personal Taste profile."}

function tasteSnapshot(){const t=clone(story().taste);story().taste.snapshot={savedAt:now(),profile:t};state.prefs.snapshots.push({id:uid('snap'),storyId:story().id,createdAt:now(),profile:t});saveState();toast('Taste snapshot saved.')}
function resetTaste(){story().taste={likes:[],dislikes:[],confidence:{},learning:true,snapshot:null,history:[]};saveState();closeOverlay();render();toast('Learned taste reset.')}
function resetTasteFromSnapshot(){const t=story().taste.snapshot?.profile;if(!t)return;story().taste=clone(t);saveState();render()}
function learnTaste(kind,text){const t=story().taste;if(!t.learning)return;const arr=kind==='like'?t.likes:t.dislikes;if(!arr.includes(text))arr.push(text);t.confidence[text]=(t.confidence[text]||0)+1;t.history.push({id:uid('th'),kind,text,at:now()});if(t.history.length>100)t.history=t.history.slice(-100);}
function undoTaste(id){const t=story().taste;t.history=(t.history||[]).filter(x=>x.id!==id);saveState();renderOverlay();toast('Learning event undone.')}
function exportTaste(){const blob=new Blob([JSON.stringify({version:1,profile:story().taste},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aurora-taste.json';a.click();URL.revokeObjectURL(url);toast('Taste profile exported.')}

function saveScene(id,close){const sc=sceneById(story(),id),ed=document.getElementById('richEditor');if(!sc||!ed)return;saveVersion(sc,'Before manual edit');sc.title=document.getElementById('sceneTitle')?.value.trim()||sc.title;sc.objective=document.getElementById('sceneObjective')?.value.trim()||sc.objective;sc.html=ed.innerHTML;sc.text=ed.innerText;updateMemoryFromScene(story(),sc,'Manual edit',sc.text);learnTaste('like','accepted manual edit');touch(story());saveState();if(close)closeOverlay();else renderOverlay();toast('Scene saved.')}
function saveCodex(type,id){const arr=story()[collection(type)],x=arr.find(a=>a.id===id);if(!x)return;x.name=document.getElementById('ceName').value.trim()||x.name;x.desc=document.getElementById('ceDesc').value.trim();x.details=document.getElementById('ceDetails').value.trim();if(type==='character'){x.visual=document.getElementById('ceVisual')?.value.trim()||'';x.role=document.getElementById('ceRole')?.value.trim()||''}touch(story());saveState();closeOverlay();render();toast('Codex entry saved.')}
function saveNewCodex(){const type=document.getElementById('newCodeType').value,name=document.getElementById('newCodeName').value.trim();if(!name)return toast('Add a name.');story()[collection(type)].push({id:uid(type.slice(0,2)),name,type,desc:document.getElementById('newCodeDesc').value.trim(),details:document.getElementById('newCodeDetails').value.trim()});touch(story());saveState();closeOverlay();render();toast('Codex entry added.')}
function saveChapter(id){const c=allChapters(story()).find(x=>x.id===id);if(!c)return;c.title=document.getElementById('chTitle').value.trim()||c.title;c.summary=document.getElementById('chSummary').value.trim();document.querySelectorAll('[data-scene-objective]').forEach(el=>{const sc=sceneById(story(),el.dataset.sceneObjective);if(sc)sc.objective=el.value});touch(story());saveState();closeOverlay();render();toast('Chapter saved.')}
function saveStory(id){const s=storyById(id);if(!s)return;s.title=document.getElementById('storyTitle').value.trim()||s.title;s.genre=document.getElementById('storyGenre').value.trim()||s.genre;s.status=document.getElementById('storyStatus').value;s.folder=document.getElementById('storyFolder').value;s.concept=document.getElementById('storyConcept').value.trim();s.premise=document.getElementById('storyPremise').value.trim();touch(s);saveState();closeOverlay();render();toast('Story updated.')}
function saveFolder(){const f=document.getElementById('newFolderName')?.value.trim();if(!f)return;if(state.folders.some(x=>x.toLowerCase()===f.toLowerCase()))return toast('That folder already exists.');state.folders.push(f);saveState();closeOverlay();render();toast('Folder created.')}
function saveSceneSettings(){const s=story();s.pov=document.getElementById('scenePov').value;s.aiWritesUser=document.querySelector('[data-scene-ai-write]')?.classList.contains('on')??s.aiWritesUser;const st=document.getElementById('sceneStyle').value;if(st==='taste'){s.authorProfileId='';s.styleId=s.styleId}else{s.authorProfileId='';s.styleId=st}touch(s);saveState();closeOverlay();render();toast('Scene settings saved.')}
function readerAdjust(n){state.settings.fontScale=Math.max(.85,Math.min(1.45,(state.settings.fontScale||1)+n));saveState();if(ui.reader)renderOverlay();else render()}
function findEditor(){const ed=document.getElementById('richEditor');if(!ed)return;let bar=document.getElementById('editorFindBar');if(bar){bar.remove();return}bar=document.createElement('div');bar.id='editorFindBar';bar.className='editor-find-bar';bar.innerHTML='<input id="editorFindInput" placeholder="Find in manuscript…"><button class="btn small" id="editorFindPrev">↑</button><button class="btn small" id="editorFindNext">↓</button><span class="tiny" id="editorFindCount"></span>';ed.parentElement.insertBefore(bar,ed);const inp=bar.querySelector('#editorFindInput');inp.focus();const update=()=>{const q=inp.value.trim();const count=q?ed.innerText.toLowerCase().split(q.toLowerCase()).length-1:0;bar.querySelector('#editorFindCount').textContent=q?`${count} matches`:'';if(q)findTextInEditor(q)};inp.oninput=update;bar.querySelector('#editorFindNext').onclick=()=>{if(inp.value)findTextInEditor(inp.value)};bar.querySelector('#editorFindPrev').onclick=()=>{if(inp.value)findTextInEditor(inp.value)} }
function findTextInEditor(q){const ed=document.getElementById('richEditor');if(!ed||!q)return false;const walker=document.createTreeWalker(ed,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const n=walker.currentNode,i=n.nodeValue.toLowerCase().indexOf(q.toLowerCase());if(i>=0){const r=document.createRange();r.setStart(n,i);r.setEnd(n,i+q.length);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(r);n.parentElement?.scrollIntoView({behavior:'smooth',block:'center'});return true}}return false}
function insertSelectedImage(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{restoreEditorSelection();document.execCommand('insertImage',false,reader.result);saveEditorSelection()};reader.readAsDataURL(file)}

function saveReaderSettings(){state.settings.readerFont=document.getElementById('rsFont')?.value||state.settings.readerFont;state.settings.readerWidth=document.getElementById('rsWidth')?.value||state.settings.readerWidth;state.settings.readerLineHeight=Number(document.getElementById('rsLine')?.value||state.settings.readerLineHeight);state.settings.readerMargin=Number(document.getElementById('rsMargin')?.value||state.settings.readerMargin);state.settings.readerPadding=Number(document.getElementById('rsPadding')?.value||state.settings.readerPadding);saveState();closeOverlay();toast('Reader settings applied.')}
function applyLibraryFilters(){state.library.folder=document.getElementById('filterFolder').value;state.library.filter=document.getElementById('filterFav').value;state.library.sort=document.getElementById('filterSort').value;saveState();closeOverlay();render()}
function testNano(){return window.nanoGPTGenerate([{role:'user',content:'Reply with exactly OK.'}],{temperature:0,max_tokens:8}).then(()=>toast('NanoGPT connection works.')).catch(e=>toast(e.message||'NanoGPT connection failed.'))}
async function nanoJSON(instruction,tag){const text=await window.nanoGPTGenerate([{role:'system',content:instruction},{role:'user',content:`Request tag: ${tag}`}],{temperature:.4,max_tokens:2600});return JSON.parse(text.replace(/^```json\s*|\s*```$/g,'').trim())}
function charge(amount){state.settings.budget.spent=Number((Number(state.settings.budget.spent||0)+amount).toFixed(3));if(state.settings.budget.spent>Number(state.settings.budget.limit||3))throw new Error('Aurora budget limit reached.');saveState()}

function exportBackup(){const payload={version:4,exportedAt:now(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aurora-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Backup exported.')}
function ensureInput(id,accept){let f=document.getElementById(id);if(!f){f=document.createElement('input');f.type='file';f.accept=accept;f.id=id;f.hidden=true;f.addEventListener('change',()=>{if(id==='backupInput')openModal('confirmRestore');if(id==='tasteInput')importTasteFile(f.files?.[0])});document.body.appendChild(f)}}
function restoreBackup(){const f=document.getElementById('backupInput')?.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);state=mergeState(x.state||x);saveState();closeOverlay();render();toast('Backup restored.')}catch{toast('That backup could not be read.')}};r.readAsText(f)}
function resetApp(){state=clone(defaults);saveState();closeOverlay();render();toast('Aurora reset.')}
function importTasteFile(f){if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);story().taste=x.profile;saveState();render();toast('Taste imported.')}catch{toast('Invalid taste file.')}};r.readAsText(f)}
function restoreSettingsFields(){const d=ui.settingsDraft;if(!d)return;setTimeout(()=>{['setReaderFont','setReaderWidth'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=d[id==='setReaderFont'?'readerFont':'readerWidth']||e.value});},0)}
function saveSettings(){syncSettingsInputs();const d=ui.settingsDraft||clone(state.settings);d.api.endpoint=document.getElementById('setEndpoint')?.value.trim()||d.api.endpoint;d.api.key=document.getElementById('setApiKey')?.value||'';d.api.model=document.getElementById('setModel')?.value.trim()||d.api.model;d.readerFont=document.getElementById('setReaderFont')?.value||d.readerFont;d.readerWidth=document.getElementById('setReaderWidth')?.value||d.readerWidth;d.readerLineHeight=Number(document.getElementById('setLineHeight')?.value||d.readerLineHeight);d.readerMargin=Number(document.getElementById('setReaderMargin')?.value||d.readerMargin);d.readerPadding=Number(document.getElementById('setReaderPadding')?.value||d.readerPadding);state.settings=clone(d);saveState();closeOverlay();render();toast('Settings saved.')}

window.nanoGPTGenerate=async function(messages,{temperature=.8,max_tokens=1200}={}){const {endpoint,key,model}=state.settings.api;if(!key)throw new Error('NanoGPT API key is not configured.');const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model,messages,temperature,max_tokens,stream:false})});if(!res.ok)throw new Error(`NanoGPT HTTP ${res.status}`);const data=await res.json();return data?.choices?.[0]?.message?.content||data?.output_text||''}


function filterCodex(q){const term=(q||'').toLowerCase();document.querySelectorAll('.codex-item').forEach(el=>{el.style.display=el.innerText.toLowerCase().includes(term)?'flex':'none'})}
function saveBranch(){const name=document.getElementById('branchName')?.value.trim()||`Branch ${(story().branches||[]).length+1}`;const idea=document.getElementById('branchIdea')?.value.trim();if(!idea)return toast('Tell Aurora what you want to test.');const sc=scCurrent(story());story().branches.unshift({id:uid('branch'),name,idea,parentScene:sc?.id||'',parentTitle:sc?.title||'Current scene',status:'Experimental',createdAt:now(),snapshot:clone({scene:sc?.text||'',memory:story().memory})});touch(story());saveState();closeOverlay();render();toast('Branch created. Main story is untouched.')}
function openBranch(id){const b=story().branches.find(x=>x.id===id);if(!b)return;ui.tipText=`${b.name}

${b.idea}

This branch is experimental. Its parent story remains unchanged until you promote it.`;openModal('tip')}
function deleteConfirmed(){deleteStory(ui.deleteStoryId)}
function promoteBranch(id){toast('Branch promotion will be enabled in the next intelligence layer.')}

// Initialize
applyTheme();ensureInput('backupInput','.json');ensureInput('tasteInput','.json');if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=4').catch(()=>{}));render();
